import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/9/","title":"第 9 课 · 时态和语态 Tenses & Voice | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 9 课 · 时态和语态 Tenses & Voice","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/9/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第九课 语法专题 · 第九课 对应教材上册 P82–P103 · 时态表明动作发生的时间和状态：四时四态组合成 16 种，本课精讲 11 种；语态考 be + done 各时态被动式与&quot;主动表被动&quot;6 条高频考点。 考点地图 · 点击跳...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 9 课 · 时态和语态 Tenses & Voice\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/9/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 9 课 · 时态和语态 Tenses & Voice"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第九课 语法专题 · 第九课 对应教材上册 P82–P103 · 时态表明动作发生的时间和状态：四时四态组合成 16 种，本课精讲 11 种；语态考 be + done 各时态被动式与&quot;主动表被动&quot;6 条高频考点。 考点地图 · 点击跳..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 9 课 · 时态和语态 Tenses & Voice"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/9/"}]]},"readingTime":{"minutes":88.49,"words":26548},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/9.md","headers":[]}`),u={name:`9.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0009-tenses-voice.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第九课`,-1)]),l[10]||=r(`<p>语法专题 · 第九课</p><p>对应教材上册 P82–P103 · 时态表明动作发生的时间和状态：四时四态组合成 16 种，本课精讲 11 种；语态考 be + done 各时态被动式与&quot;主动表被动&quot;6 条高频考点。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>时态</strong>：表明动作发生的<strong>时间和状态</strong>；四时（现在/过去/将来/过去将来）× 四态（一般/进行/完成/完成进行）= 16 种，精讲 11 种</a></li><li><a href="#pt-2"><strong>语态</strong>：主动语态 / 被动语态（各时态被动式 + 主动表被动 6 条——高频考点）</a></li></ol></div><h2 id="时态总览-·-16-种时态结构总表" tabindex="-1"><a class="header-anchor" href="#时态总览-·-16-种时态结构总表"><span>时态总览 · 16 种时态结构总表</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 时态总览 · 16 种时态结构总表</p><ul><li><strong>目标</strong>：把“时态”看成时间轴上的格子：先分清四时四态 16 种结构，再把一般现在、一般过去、一般将来落到标志词与主将从现上。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>时态总览（四时四态 16 种）</code> <code>一般现在时 / 一般过去时 / 一般将来时</code></li></ul></div><h3 id="时态总览-·-16-种时态结构总表-·-小步学" tabindex="-1"><a class="header-anchor" href="#时态总览-·-16-种时态结构总表-·-小步学"><span>时态总览 · 16 种时态结构总表 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>时态：时间和动作状态一起看</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>时态 = 谓语动词随“时间”换形态</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>一般现在时：习惯、真理和“时刻表”</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>一般过去时与一般将来时：时间轴上的前后两格</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：合上书，说出四时四态怎样组合成 16 种时态，并给一般现在、一般过去、一般将来各举一个时间标志词。</p><div class="hint-container tip"><p class="hint-container-title">时态 = 谓语动词随“时间”换形态</p><p><strong>句意</strong>：我昨天买了一本书。／我每天买一本书。／我明天买一本书。三句话的成分、意思只差时间，英语里的动词却要跟着换：bought / buy / will buy。</p><p><strong>拆解</strong></p><ul><li>I bought a book yesterday：主语 I + 谓语 bought（过去式）+ 宾语 a book + 时间状语 yesterday</li><li>I buy a book every day：同一套成分，谓语换成 buy（原形），时间状语换成 every day</li><li>I will buy a book tomorrow：谓语换成 will + 动词原形 buy，时间状语换成 tomorrow</li><li>三句的主语和宾语都没动，唯一变化的是谓语动词的形态——这就是时态</li></ul><p><strong>语法</strong>：时态 = 时间（现在 / 过去 / 将来 / 过去将来）× 状态（一般 / 进行 / 完成 / 完成进行），共 16 种，本课精讲 11 种。做题顺序固定：先抓时间状语定时间，再看动作的状态，最后把谓语写成对应结构。</p><ol><li><strong>过去</strong> did / was / were——动作或状态发生在过去，与现在不挂钩</li><li><strong>现在</strong> do/does、am/is/are——反复的习惯、客观真理、当前的状态</li><li><strong>将来</strong> will do、be going to do——将要发生的事、打算与计划</li><li><strong>过去将来</strong> would do——站在过去看将来，多出现在 said、told 等过去时动词的宾语从句里</li></ol><p>正例：I bought a book yesterday.（过去的动作）；I buy a book every day.（现在的习惯）；I will buy a book tomorrow.（将来的打算） 反例：I buy a book yesterday. ×（buy 是一般现在时，与 yesterday 冲突）；I will bought a book. ×（will 后面必须用动词原形 buy）；I bought a book every day. ×（过去式不能表示现在的习惯） 适用边界：“找时间状语定时态”只在有明确时间参照时最好用：每个时间状语都有默认搭档（yesterday→过去、every day→一般现在、next year→将来）。句中没有时间状语时，改看动作之间的先后关系，而不是凭感觉。</p><p><strong>口诀</strong>：时态 = 时间 + 状态，谓语动词跟着时间换形态 —— 中文靠“昨天、每天、明天”这些时间词表时间，动词不变；英语必须把时间标在谓语动词上，所以先找时间状语，再定谓语形态。</p></div><div class="hint-container tip"><p class="hint-container-title">一般现在时：习惯、真理和“时刻表”</p><p><strong>句意</strong>：John reads an English passage every day, so he has a wide vocabulary. 意思是“约翰每天读一篇英语短文，所以他的词汇量很广”；The next train leaves at 3 o&#39;clock this afternoon. 意思是“下一班火车今天下午三点发车”。</p><p><strong>拆解</strong></p><ul><li>John reads：主语 John 是第三人称单数，谓语 read 加 -s</li><li>every day 是频率状语，说明这是经常性、习惯性的动作</li><li>so he has a wide vocabulary：后一分句用同一种时态承接结果</li><li>The next train leaves at 3 o&#39;clock：leaves 是一般现在时，表示的却是将来——因为这是时刻表上已安排好的事</li></ul><p><strong>语法</strong>：一般现在时：主语 + do/does，或主语 + am/is/are。三单变化：一般加 -s，s/x/ch/sh/o 结尾加 -es，辅音字母 + y 变 i 加 -es，特殊 have → has。四类用法：习惯性动作、状态与特征、客观真理、按计划安排（时刻表）。主将从现：时间、条件状语从句用一般现在时表将来，主句才用将来时。</p><ol><li><strong>现在（反复）</strong> always / usually / often / every day / twice a week——反复发生的习惯</li><li><strong>现在（真理）</strong> The Earth moves around the sun.——永真的客观事实</li><li><strong>将来（安排）</strong> The next train leaves at 3 o&#39;clock.——时刻表、日程里已定的事</li><li><strong>省略的将来</strong> if / when 从句用一般现在时，主句用 will do（主将从现）</li></ol><p>正例：John reads an English passage every day.（习惯）；The Earth moves around the sun.（客观真理）；They will hold a party if they complete the project on time.（主将从现） 反例：They will hold a party if they will complete the project. ×（if 条件状语从句里不用将来时）；He go to school every day. ×（第三人称单数漏了 -s） 适用边界：一般现在时表将来只限两类：① come、go、leave、arrive、start 等趋向动词按计划即将发生的动作；② 时刻表、日程（leaves、starts）。其他动词表将来仍要用 will 或 be going to。客观真理不受主句时态影响：The children learned that autumn is the season of falling leaves.</p><p><strong>口诀</strong>：主将从现：主句将来，从句现在 —— “将来”只标在主句上；if / when 引导的时间、条件状语从句里不写 will，用一般现在时顶替将来。</p></div><div class="hint-container tip"><p class="hint-container-title">一般过去时与一般将来时：时间轴上的前后两格</p><p><strong>句意</strong>：The plane arrived on time yesterday, but traffic was awful. 意思是“飞机昨天准时到达，但交通很糟糕”；The city will build a bridge across the river next year. 意思是“这座城市明年将在河上建一座桥”。</p><p><strong>拆解</strong></p><ul><li>The plane arrived：arrived 是过去式，与 yesterday 呼应</li><li>but traffic was awful：but 后面的分句同样用过去时，两个分句时态保持一致</li><li>The city will build：will + 动词原形构成一般将来时</li><li>next year：将来时间状语，给 will build 定位</li></ul><p><strong>语法</strong>：一般过去时：主语 + did，或主语 + was/were。过去式变化“直去双改”：直接加 -ed、去 e 加 d、辅元辅双写加 -ed、辅音字母 + y 变 i 加 -ed。一般将来时：will/shall do、be going to do、be about to do（后面不跟明确时间状语）、be to do（按约定、计划、职责）。</p><ol><li><strong>过去</strong> yesterday / last week / ago / just now / the other day——arrived、went、was</li><li><strong>现在</strong> （对照）一般现在时表习惯：arrives、goes、is</li><li><strong>将来</strong> tomorrow / next year / in a few minutes——will build、be going to build</li><li><strong>马上要发生</strong> be about to do——即将发生，句子里不再跟明确时间状语</li></ol><p>正例：The plane arrived on time yesterday.（过去）；I went to the park yesterday and saw a lot of beautiful flowers.（两个并列谓语都用过去式）；The city will build a bridge next year.（将来） 反例：Did you went to the party last weekend? ×（助动词 Did 后必须用原形 go）；The city will builds a bridge. ×（will 后要用原形） 适用边界：疑问句和否定句里“过去”只标在助动词 did 上（Did you go…?），实义动词回原形；will 后面一律用原形。be about to do 表示“马上”，不能再加上 tomorrow 这类明确时间状语。</p><p><strong>口诀</strong>：过去式“直去双改”；助动词后一律用原形 —— 直=直接加 -ed，去=去 e 加 d，双=辅元辅双写加 -ed，改=辅音字母 + y 变 i 加 -ed。did / will 后接原形，避免同一句里把过去或将来标两遍。</p></div><table><thead><tr><th></th><th>一般</th><th>进行</th><th>完成</th><th>完成进行</th></tr></thead><tbody><tr><td><strong>现在</strong></td><td>do/does</td><td>am/is/are + doing</td><td>have/has done</td><td>have/has been doing</td></tr><tr><td><strong>过去</strong></td><td>did/was/were</td><td>was/were doing</td><td>had done</td><td>had been doing</td></tr><tr><td><strong>将来</strong></td><td>shall/will do</td><td>shall/will be doing</td><td>shall/will have done</td><td>shall/will have been doing</td></tr><tr><td><strong>过去将来</strong></td><td>should/would do；was/were going to do</td><td>should/would be doing</td><td>should/would have done</td><td>should/would have been doing</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>感受中英文时态差异 我昨天买了一本书。I <strong>bought</strong> a book yesterday. / 我每天买一本书。I <strong>buy</strong> a book every day. / 我明天买一本书。I <strong>will buy</strong> a book tomorrow.</p><p>英语中的时态，是<strong>谓语动词随着时间的变化而产生的不同形态的变化</strong>。</p></div><h2 id="一、时态-11-种" tabindex="-1"><a class="header-anchor" href="#一、时态-11-种"><span>一、时态（11 种）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 一、时态（11 种）</p><ul><li><strong>目标</strong>：把进行时、完成时和过去将来时挂在同一条时间轴上：进行时管“正在”，现在完成管“到现在的经历与持续”，过去完成管“过去的过去”，将来完成管“到将来某时为止”。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>进行时（现在 / 过去 / 将来进行时）</code> <code>现在完成时（have/has done）</code> <code>过去完成时（过去的过去）</code> <code>将来完成时（will have done）</code> <code>现在完成进行时（have/has been doing）</code> <code>过去将来时（would do）</code></li></ul></div><h3 id="一、时态-11-种-·-小步学" tabindex="-1"><a class="header-anchor" href="#一、时态-11-种-·-小步学"><span>一、时态（11 种） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>时态：时间和动作状态一起看</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>进行时三兄弟：正在进行的动作当背景</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>现在完成时：到现在为止的结果与经历</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>过去完成时：过去的过去</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>将来完成、现在完成进行与过去将来：时间轴的另外三格</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句时间轴串起进行时、现在完成、过去完成、将来完成：各说出它的结构和一个标志词。</p><div class="hint-container tip"><p class="hint-container-title">进行时三兄弟：正在进行的动作当背景</p><p><strong>句意</strong>：I was talking on the phone when John came in. 意思是“约翰进来的时候，我正在打电话”；At this time next week, we will be discussing the matter with our friends. 意思是“下周这个时候，我们将正在与朋友们讨论这件事”。</p><p><strong>拆解</strong></p><ul><li>I was talking on the phone：was + doing 构成过去进行时，表示过去某一时刻正在进行</li><li>when John came in：when 从句用一般过去时（came），给出“打断”的那个时间点</li><li>两个动作的关系：长动作 was talking 作背景，短动作 came in 打点</li><li>At this time next week + will be discussing：将来的某一时刻正在做 → 将来进行时</li></ul><p><strong>语法</strong>：进行时 = be + doing，be 负责时态与人称。现在进行时 am/is/are doing；过去进行时 was/were doing；将来进行时 will/shall be doing。进行时只说明“在某个时刻正在进行”，不表示完成、也不表示次数。</p><ol><li><strong>现在</strong> now / right now / at the moment / these days / Look!——am/is/are doing</li><li><strong>过去某时刻</strong> at 8 o&#39;clock yesterday / at that time / when + 过去时——was/were doing</li><li><strong>将来某时刻</strong> at this time next week / tomorrow evening——will be doing</li><li><strong>背景与打点</strong> 长动作用进行时作背景，短动作用一般过去时打点：I was eating dinner when my dog came in.</li></ol><p>正例：Look! The children are playing in the park.（此刻正在进行）；At 8 o&#39;clock yesterday, she was taking a shower.（过去某时刻）；He is studying for the test these days.（现阶段持续进行） 反例：At 8 o&#39;clock yesterday, she took a shower. ×（“那一点正在洗”要用进行时）；Look! The children play in the park. ×（Look! 提示正在进行） 适用边界：进行时不能表示“累计了多久、多少次”（那是完成时的任务）；系动词 feel、seem 等一般不用进行时（is seeming ×）。用进行时表将来（I&#39;m leaving for Beijing.）只限按计划即将发生的动作。</p><p><strong>口诀</strong>：现在进行看 now / Look!，过去进行看 at that time，将来进行看 at this time next week —— 三步定位：先在时间轴上定位置（现在 / 过去 / 将来），再确认状态是“正在进行”，最后套 be + doing。</p></div><div class="hint-container tip"><p class="hint-container-title">现在完成时：到现在为止的结果与经历</p><p><strong>句意</strong>：I have seen this movie three times. 意思是“这部电影我看过三遍”；They have lived in Beijing since 2010. 意思是“他们从 2010 年起就住在北京”。</p><p><strong>拆解</strong></p><ul><li>I have seen：have + 过去分词构成现在完成时</li><li>three times：次数表示累计经历，是现在完成时的典型用法</li><li>They have lived in Beijing：动作从过去持续到现在，还可能继续</li><li>since 2010：since + 时间点，是现在完成时的标志</li></ul><p><strong>语法</strong>：现在完成时 = have/has + done。两大用法：① 已完成——动作结束但对现在有影响；② 未完成——从过去开始持续到现在。标志词：already / just / yet、never / ever、so far = by now、since + 时间点、for + 一段时间。have been to 去过（已回来）／have gone to 去了（还没回来）。</p><ol><li><strong>过去某时间点</strong> since 2010 / since last week——持续动作的起点</li><li><strong>过去到现在</strong> for ten years / so far / these years——持续的时间段</li><li><strong>现在（结果）</strong> I have just eaten a hamburger.——动作结束了，强调现在的状态（还饱着）</li><li><strong>现在（经历）</strong> three times / ever / never——累计到现在的经历次数</li></ol><p>正例：I have already finished my homework.（结果）；He has lived in this city for ten years.（持续）；Have you ever been to Japan?（经历） 反例：They have lived in Beijing in 2010. ×（in 2010 是明确的过去时间点，不能配现在完成时）；Tom has worked there two years ago. ×（two years ago 与现在完成时冲突） 适用边界：现在完成时不能与明确的过去时间状语连用（yesterday、last week、in 2010、just now）；非延续性动词（buy、die、join、begin）不能与 for + 时间段连用。区分 have been to（去过，人已回）与 have gone to（去了，人未回）。</p><p><strong>口诀</strong>：b：有去必有回（been to 去过）；g：刚去还未回（gone to 去了） —— 看助动词的第二个字母就知道人回来没有：be-en 有回，go-ne 未回。</p></div><div class="hint-container tip"><p class="hint-container-title">过去完成时：过去的过去</p><p><strong>句意</strong>：By the time I got to the station, the train had left. 意思是“我到达车站时，火车已经开走了”；When I came into the classroom, my dear students had begun reading. 意思是“我走进教室时，同学们已经开始朗读了”。</p><p><strong>拆解</strong></p><ul><li>By the time I got to the station：从句用一般过去时，给出一个过去的时间点</li><li>the train had left：had + 过去分词，表示在这个过去时间点之前已经发生</li><li>两个动作的先后：left 在前，got 在后</li><li>没有时间状语时同理：begin 在前，came 在后</li></ul><p><strong>语法</strong>：过去完成时 = had + done，表示“过去的过去”。常见触发条件：by the time + 过去时、before / after 引导的句子、宾语从句里主句是过去时且从句动作更早、It/This was the first time that + had done、by the end of + 过去时间。</p><ol><li><strong>更早的过去</strong> had left / had begun——先发生的动作用过去完成时</li><li><strong>过去的参照点</strong> got to the station / came into the classroom——后发生的动作用一般过去时</li><li><strong>现在（对照）</strong> 现在完成时 have/has done——参照点是“现在”</li><li><strong>过去将来</strong> would do——站在过去看将来：John said he would have a rest the next day.</li></ol><p>正例：By the time I got to the station, the train had left.；We had just finished our assignment when the teacher came in.；By the end of last month, we had learned 5000 words. 反例：By the time I got to the station, the train left. ×（没有交代“更早”这一层）；We have finished our assignment when the teacher came in. ×（when 从句是过去时，主句该用过去完成） 适用边界：只有一个过去动作时不能用过去完成时——它必须有“更早”这个参照点。宾语从句里如果从句内容是客观真理，仍用一般现在时：The children learned that autumn is the season of falling leaves.</p><p><strong>口诀</strong>：先发生用 had done，后发生用 did；by the time + 过去 → 主句过去完成 —— 时间轴上有两个过去点，靠前的配 had，靠后的配过去式；只有一个过去点就别急着写 had。</p></div><div class="hint-container tip"><p class="hint-container-title">将来完成、现在完成进行与过去将来：时间轴的另外三格</p><p><strong>句意</strong>：By the time you get to New York, I will have left for London. 意思是“等你到纽约时，我将已经动身去伦敦了”；I have been learning English since three years ago. 意思是“我从三年前起就一直在学英语”。</p><p><strong>拆解</strong></p><ul><li>By the time you get to New York：从句用一般现在时表将来</li><li>I will have left：will have + done，表示在将来某一时刻之前完成</li><li>have been learning：have/has been + doing 构成现在完成进行时，强调一直进行</li><li>since three years ago：since + 一段时间 + ago，给“持续”定起点</li></ul><p><strong>语法</strong>：将来完成时 = will/shall have done，标志是 by + 将来时间、by the time + 现在时；现在完成进行时 = have/has been doing，强调动作一直在进行（现在的完成时强调结果）；过去将来时 = would do、was/were going to do，用于 said、told、knew、thought 等过去时动词后的宾语从句。</p><ol><li><strong>起点</strong> since three years ago——现在完成进行时从过去某点开始</li><li><strong>到现在为止</strong> have been learning——一直进行，可能还要继续</li><li><strong>将来某时之前</strong> by the time… / by the end of next year——will have done</li><li><strong>过去的将来</strong> John said he would have a rest the next day.——would do</li></ol><p>正例：By the time you get to New York, I will have left for London.（将来完成）；I have been reading this book these days.（持续）；John said he would have a rest the next day.（过去将来） 反例：By the time you get to New York, I have left for London. ×（将来某时之前完成要用将来完成时）；强调“一直下雪”时写成 It has just snowed. ×（那是结果，应用 has been snowing） 适用边界：将来完成时必须有一个将来时间点（by / by the time + 现在时）；现在完成时强调结果（It has just snowed. 雪停了），现在完成进行时强调持续（It has been snowing. 还在下）；过去将来时只出现在主句是过去时的语境里。</p><p><strong>口诀</strong>：by + 将来 → will have done；by the time + 过去 → had done；have been doing 强调“一直在做” —— 同一句“到……为止”，看 by 后面是将来还是过去，就能定下完成时的种类。</p></div><h3 id="_1-一般现在时-教材-p83-85" tabindex="-1"><a class="header-anchor" href="#_1-一般现在时-教材-p83-85"><span>1. 一般现在时（教材 P83-85）</span></a></h3><p><strong>含义</strong>：表示通常性、规律性、习惯性、真理性（即事实）的动作或状态。</p><p><strong>结构</strong>：主语 + do/does；主语 + am/is/are。例：In fact, it <strong>takes</strong> a lifetime to master the game.</p><p><strong>时间标志词</strong>：always, usually, every morning/night/evening/day/week/year, often, sometimes, occasionally, from time to time, twice a week</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>什么是第三人称单数 主语<strong>非 I、非 you、非复数</strong>，就是第三人称单数。此时谓语动词变三单形式：一般在动词后加 -s；以 s/x/ch/sh/o 结尾加 -es；辅音字母+y 的去 y 变 i 加 es；特殊：have → has。</p><p>The concert <strong>begins</strong> at 7:00 p.m. / Tom <strong>lives</strong> in New York.</p></div><p><strong>用法</strong>：</p><ol><li>表示经常的或习惯性的动作，常与频率时间状语连用：I <strong>leave</strong> home for school at 7:00 every morning.</li><li>描述主语的状态、性质、特征、能力等：She <strong>is</strong> straightforward（adj. 直率的）.</li><li>陈述客观真理、客观存在、科学事实：The Earth <strong>moves</strong> around the sun.</li><li>表示格言或警句：<strong>Where there is life, there is hope.</strong> 生命不息，希望长在。</li><li><strong>表示将来</strong>： ① 按规定、计划、安排将要发生的动作（仅限&quot;来、去、动、停、开始、结束、继续&quot;类趋向动词 come, go, arrive, leave, start, begin, return 等）：The next train <strong>leaves</strong> at 3 o&#39;clock this afternoon.</li></ol><p>② <strong>主将从现</strong>（时间/条件状语从句中，主句用一般将来时，从句用一般现在时）：<strong>When Bill comes</strong>, I <strong>will go</strong> to have dinner with him.</p><h3 id="_2-一般过去时-教材-p85-86" tabindex="-1"><a class="header-anchor" href="#_2-一般过去时-教材-p85-86"><span>2. 一般过去时（教材 P85-86）</span></a></h3><p><strong>含义</strong>：过去某个时间里发生的动作或状态；过去习惯性、经常性的动作或行为。</p><p><strong>结构</strong>：主语 + did；主语 + was/were。</p><p><strong>时间标志词</strong>：yesterday (morning/afternoon/evening), the day before yesterday, last night (week, Sunday, weekend), ago, this morning/afternoon/evening, when 引导的状语从句（动词过去时）, just now, the other day, a few days ago。</p><p>真题例：The plane <strong>arrived</strong> on time yesterday, but traffic was awful.【24湖南】</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀 · 动词过去式变化规则<strong>直去双改</strong>——<strong>直</strong>：一般词尾直接 +ed（look → looked）；<strong>去</strong>：词尾有个 e，加个 d 就可以（like → liked）；<strong>双</strong>：辅元辅结尾，双写词尾 +ed（plan → planned）；<strong>改</strong>：辅音字母+y 结尾，变 y 为 i +ed（study → studied）</p></div><h3 id="_3-一般将来时-教材-p86-87" tabindex="-1"><a class="header-anchor" href="#_3-一般将来时-教材-p86-87"><span>3. 一般将来时（教材 P86-87）</span></a></h3><p><strong>含义</strong>：将要发生的动作或存在的状态，及打算、计划或准备做某事。</p><p><strong>结构</strong>：主语 + am/is/are + going to + do；主语 + will/shall + do；be about to do；be to do。</p><p><strong>时间标志词</strong>：tomorrow, next day (week, month, year...), soon, in a few minutes, the day after tomorrow。</p><p><strong>用法</strong>：</p><ol><li>表示将要发生的动作或情况。注意：<strong>shall 表示将来</strong>意为&quot;将；会&quot;，用于第一人称（I 和 we）：I <strong>shall be</strong> back soon.</li><li>&quot;<strong>be going to</strong> + 动词原形&quot;表示即将发生的或打算进行的事：Dad and I <strong>are going to watch</strong> an opera this afternoon.</li><li>&quot;<strong>be about to do</strong>&quot;表示即将发生的动作，&quot;马上要做某事&quot;，后面<strong>不跟明确时间状语</strong>：We <strong>are about to start</strong>.</li><li>&quot;<strong>be to do</strong>&quot;表示约定、计划、命令或职责义务要做的事：He <strong>is to visit</strong> Japan next year.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>in + 一段时间，时态取决于语境</p><ol><li><p><strong>in + 将来一段时间</strong>，用一般将来时，译为&quot;……之后&quot;：He will come back <strong>in a month</strong>. 他一个月后回来。</p></li><li><p><strong>in + 过去一段时间</strong>，可以用现在完成时：<strong>In the last 40 years</strong>, great changes <strong>have taken</strong> place in China. 在过去的 40 年里，中国发生了巨大的变化。</p></li><li><p><strong>in + 过去时间段</strong>，也可以用一般过去时：He <strong>finished</strong> his homework in half an hour yesterday. 他昨天用了半小时完成了作业。</p></li></ol></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>行进式动词&quot;进行/一般现在表将来&quot;</p><ol><li><p><strong>现在进行表将来</strong>：go, come, start, move, sail, leave, arrive, stay, live, fly 等可用进行时态表示按计划即将发生的动作：I&#39;<strong>m leaving</strong> for Beijing. 我将动身去北京。</p></li><li><p><strong>一般现在时表将来</strong>：come, go, leave, arrive, start, get, stay, live, fly 等的一般现在时也可表示将来，主要表示<strong>时间上已确定或安排好的事情</strong>：The meeting <strong>starts</strong> at five o&#39;clock. 会议五点开始。</p></li></ol></div><h3 id="_4-现在进行时-教材-p88" tabindex="-1"><a class="header-anchor" href="#_4-现在进行时-教材-p88"><span>4. 现在进行时（教材 P88）</span></a></h3><p><strong>含义</strong>：表示现阶段或说话时正在进行的动作及行为。</p><p><strong>结构</strong>：主语 + be (am/is/are) + doing + 其他。</p><p><strong>时间标志词</strong>：now, this week, right now, just now, at the moment, at present，look, listen, smell 等。</p><ol><li>表示说话时正在进行的动作或发生的事情：We <strong>are waiting</strong> for you.</li><li>表示现阶段处于进行之中的动作，但说话时不一定正在进行：Tom <strong>is studying</strong> medicine while his sister <strong>is doing</strong> ecology.</li><li>与 <strong>always, constantly, forever, continually</strong> 等连用，表示反复出现或习惯性的动作，往往带有说话人的主观色彩：You <strong>are always changing</strong> your mind.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀 · 现在分词（v-ing）变化规则<strong>直去双改</strong>——<strong>直</strong>：多数在动词后直接加 ing（talk → talking）；<strong>去</strong>：以不发音的 e 结尾，去 e 加 ing（make → making）；<strong>双</strong>：辅元辅且重读音节，双写词尾 +ing（stop → stopping）；<strong>改</strong>：以 ie 结尾，把 ie 改为 y 再加 ing（die → dying）</p></div><h3 id="_5-过去进行时-教材-p89" tabindex="-1"><a class="header-anchor" href="#_5-过去进行时-教材-p89"><span>5. 过去进行时（教材 P89）</span></a></h3><p><strong>含义</strong>：表示过去某段时间或某一时刻正在发生或进行的行为或动作。</p><p><strong>结构</strong>：肯定：主语 + was/were + doing；否定：主语 + was/were + not + doing。</p><p><strong>时间标志词</strong>：at this time yesterday, at that time, the whole morning, all day yesterday, from January to March last year，或 when 引导的谓语动词为一般过去时的时间状语等。</p><p>例：I <strong>was talking</strong> on the phone when John <strong>came</strong> in.</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>过去进行时与一般过去时互为时间背景 结构：主语 1 + was/were doing，when + 主语 2 + did...</p><p>我当时正在吃饭的时候，我的狗进来了。→ I <strong>was eating</strong> dinner <strong>when</strong> my dog <strong>came</strong> in.</p></div><h3 id="_6-将来进行时-教材-p90" tabindex="-1"><a class="header-anchor" href="#_6-将来进行时-教材-p90"><span>6. 将来进行时（教材 P90）</span></a></h3><p><strong>含义</strong>：表示将来某一时间正在进行的动作，或要在将来某一时间开始并继续下去的动作。常用来表示询问、请求等。</p><p><strong>结构</strong>：主语 + shall/will + be + doing。</p><p><strong>时间标志词</strong>：soon, tomorrow, this evening, on Sunday, by this time, in two days, tomorrow evening。</p><ol><li>表示在将来某一时间正在进行的动作：At this time on Wednesday morning, she <strong>will be listening</strong> to Mozart.</li><li>表示安排要做的事或预计会发生的事：I&#39;<strong>ll be meeting</strong> you tomorrow evening.</li></ol><h3 id="_7-现在完成时-教材-p91-94-高频" tabindex="-1"><a class="header-anchor" href="#_7-现在完成时-教材-p91-94-高频"><span>7. 现在完成时（教材 P91-94，高频）</span></a></h3><p><strong>含义</strong>：过去发生或已经完成的动作<strong>对现在造成的影响或结果</strong>，或从过去已经开始<strong>持续到现在</strong>的动作或状态。</p><p><strong>结构</strong>：肯定：主语 + have/has + done；否定：主语 + have/has + not + done。</p><p><strong>时间标志词</strong>：yet（否定句中：尚且；疑问句中：已经）、already（已经）、just（刚刚）；never（从未）、ever（曾经）、so far = by now（迄今为止）；<strong>since + 时间点；for + 一段时间</strong>。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀 · 过去分词变化规则（直去双改）动词后<strong>直</strong>接加 ed；以 e 结尾<strong>去</strong> e 直接加 d；重读音节结尾<strong>双</strong>写词尾 +ed；辅音字母+y 结尾<strong>改</strong> y 为 i +ed</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>since 的三种接法 ① since + 过去时间点；② since + 一段时间 + ago；③ since + 句子（since + 主语 + did）</p><p>We haven&#39;t seen each other <strong>since last week</strong>. / The team has practiced daily <strong>since a week ago</strong>. / She has been happier <strong>since she moved to</strong> the countryside.</p></div><p><strong>用法</strong>：</p><ol><li><strong>已完成</strong>：动作已发生并结束，但对现在产生了影响，强调现在的状况：I <strong>have already read</strong> the novel at least three times. 这本小说我至少已经读了三遍了。（结果：已读过）</li><li><strong>未完成</strong>：动作开始于过去，持续到现在，或刚刚结束，或进行之中，还可能继续持续下去：He <strong>has lived</strong> in the village all his life.</li></ol><p><strong>时间标志词例句</strong>：I <strong>have already finished</strong> my homework. / <strong>Have</strong> you finished your work <strong>yet</strong>? / He <strong>has lived</strong> in this city <strong>for ten years</strong>. / We <strong>haven&#39;t seen</strong> each other <strong>since last week</strong>. / We <strong>haven&#39;t had</strong> any trouble <strong>so far</strong>.</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>拓展 1 · 现在完成时 vs 一般过去时 现在完成时强调<strong>对现在的影响和结果</strong>，与现在有联系；一般过去时强调动作发生的<strong>时间在过去</strong>，不涉及对现在的影响。</p><p>I <strong>ate</strong> a hamburger yesterday. 我昨天吃了一个汉堡。（强调是过去吃的，现在想不想吃不知道）</p><p>I <strong>have just eaten</strong> a hamburger. 我刚刚已经吃了一个汉堡了。（强调已经吃了，现在还饱着）</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>拓展 2 · has been to vs has gone to ① <strong>have been to</strong> 表示<strong>去过</strong>某地（现在已经回来了）：She <strong>has been to</strong> Paris (three times). 她去过巴黎（三次）。</p><p>② <strong>have gone to</strong> 表示<strong>到某地去了</strong>（现在还没回来）：She <strong>has gone to</strong> Paris. 她去巴黎了。（目前在巴黎）</p><p>口诀：<strong>b：有去必有回，因此为&quot;去过&quot;；g：刚去还未回，因此为&quot;去了&quot;</strong></p></div><h3 id="_8-过去完成时-教材-p95-96-高频" tabindex="-1"><a class="header-anchor" href="#_8-过去完成时-教材-p95-96-高频"><span>8. 过去完成时（教材 P95-96，高频）</span></a></h3><p><strong>含义</strong>：以过去某个时间为标准，在此以前发生的动作或行为，即&quot;<strong>过去的过去</strong>&quot;。</p><p><strong>结构</strong>：肯定：主语 + had + done；否定：had + not + done。</p><p>例：I <strong>had stayed</strong> there for 3 years when you graduated.</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>无时间状语时 两个动作均发生在过去：<strong>先发生</strong>的动作用过去完成时，<strong>后发生</strong>的动作用一般过去时。</p><p>练：When I came into the classroom, my dear students <strong>had begun</strong> reading.</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>before / after 与过去完成时 <strong>Before</strong> + 主语 + did，主语 + <strong>had done</strong>；<strong>After</strong> + 主语 + <strong>had done</strong>，主语 + did。</p><p>例 1：在他做自我介绍之前，我就把他的名字读了出来。<strong>Before</strong> he <strong>introduced</strong> himself, I <strong>had read</strong> his name out.</p><p>例 2：在我读出他的名字之后，他做了自我介绍。<strong>After</strong> I <strong>had read</strong> his name, he <strong>introduced</strong> himself.</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>&quot;第几次&quot;句型 <strong>It/This is</strong> the + 序数词 + time + that + 主语 + <strong>have/has done</strong>（现在）；<strong>It/This was</strong> the + 序数词 + time + that + 主语 + <strong>had done</strong>（过去）。</p><p>This is the first time that I <strong>have heard</strong> of this news.</p><p>This was the first time that I <strong>had encountered</strong> such a difficult problem.</p></div><h3 id="_9-将来完成时-教材-p97" tabindex="-1"><a class="header-anchor" href="#_9-将来完成时-教材-p97"><span>9. 将来完成时（教材 P97）</span></a></h3><p><strong>含义</strong>：在将来某一时刻之前完成的动作或状态。</p><p><strong>结构</strong>：主语 + be going to/will/shall + have done。</p><p><strong>时间标志词</strong>：by the time of + 将来的时间；by + 将来的时间。</p><p><strong>用法</strong>：表示在将来某一时间之前完成的动作：</p><p><strong>By the end of the year</strong>, she <strong>will have worked</strong> for the company for ten years. 到年底，她在这家公司工作就满十年了。</p><h3 id="_10-现在完成进行时-教材-p97-98" tabindex="-1"><a class="header-anchor" href="#_10-现在完成进行时-教材-p97-98"><span>10. 现在完成进行时（教材 P97-98）</span></a></h3><p><strong>含义</strong>：表示从过去某一时间开始一直延续到现在的动作。这一动作可能刚刚开始，也可能仍在继续，并可能延续到将来。</p><p><strong>结构</strong>：主语 + have/has + been + doing。</p><p><strong>时间标志词</strong>：since + 时间点，for + 时间段，these days。</p><p><strong>用法</strong>：表示动作从过去某一时间开始进行，一直延续到说话时刻还在继续：</p><p>I <strong>have been learning</strong> English since three years ago.</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>现在完成时 vs 现在完成进行时 现在完成时：强调<strong>结果</strong>和对现在造成的影响 → It <strong>has just snowed</strong>.（雪已停）</p><p>现在完成进行时：动作在过去一段时间内<strong>一直进行</strong>，强调<strong>持续发生性</strong> → I <strong>have been reading</strong> this book these days.（还在读）</p></div><h3 id="_11-过去将来时-教材-p99" tabindex="-1"><a class="header-anchor" href="#_11-过去将来时-教材-p99"><span>11. 过去将来时（教材 P99）</span></a></h3><p><strong>含义</strong>：表示在过去某时看来将要发生的动作或存在的状态。</p><p><strong>结构</strong>：主语 + would do；主语 + was/were going to do。</p><p><strong>时间标志词</strong>：一般用于 told, said, knew, heard, thought 等一般过去时动词后的<strong>宾语从句</strong>中。</p><p>例：John said he <strong>would have</strong> a rest the next day.</p><h2 id="二、被动语态-教材-p99-103" tabindex="-1"><a class="header-anchor" href="#二、被动语态-教材-p99-103"><span>二、被动语态（教材 P99-103）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 二、被动语态（教材 P99-103）</p><ul><li><strong>目标</strong>：先会判断“要不要用被动”（宾语变主语、be + done），再掌握各时态被动式与“主动表被动”6 条，最后分清被动语态和系表结构。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>被动语态（be + done 及各时态被动式）</code> <code>主动表被动 6 条</code> <code>被动语态与系表结构的区别</code></li></ul></div><h3 id="二、被动语态-教材-p99-103-·-小步学" tabindex="-1"><a class="header-anchor" href="#二、被动语态-教材-p99-103-·-小步学"><span>二、被动语态（教材 P99-103） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>时态：时间和动作状态一起看</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>被动语态的格式：be + done</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>主动表被动 6 条：形式是主动，意思是被动</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>被动语态与系表结构：同一个 be + done，两种身份</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出被动语态的格式和三种时态的被动式，再举出两条“主动表被动”的例子。</p><div class="hint-container tip"><p class="hint-container-title">被动语态的格式：be + done</p><p><strong>句意</strong>：He beat his kid. → His kid was beaten by him. 意思是“他打他的孩子”→“他的孩子被他打”。</p><p><strong>拆解</strong></p><ul><li>主动句：主语 He（动作发出者）+ 谓语 beat + 宾语 his kid</li><li>第一步：把宾语 his kid 提到主语位置</li><li>第二步：谓语换成 be + done，was beaten；be 的数和时态跟新主语、原句时态一致</li><li>第三步：原来的主语用 by 引出（by him），不知道或不必要说出时可以省略</li></ul><p><strong>语法</strong>：被动语态 = be + done：be 负责时态和单复数，done 不变。各时态被动式：一般现在 be done、一般过去 was/were done、一般将来 will be done、现在完成 have/has been done、过去完成 had been done、现在进行 be being done、过去进行 was/were being done，情态动词 + be done。</p><ol><li><strong>过去</strong> was/were done——The new bridge was built last month.</li><li><strong>更早的过去</strong> had been done——到过去的某个时间点之前被完成</li><li><strong>现在</strong> be done / have/has been done——are published / have been drawn</li><li><strong>此刻正在进行</strong> be being done——A new song is being played on the radio right now.</li><li><strong>将来</strong> will be done / 情态动词 + be done——will be built / must be returned</li></ol><p>正例：The new bridge was built last month.（一般过去时被动）；A new song is being played on the radio right now.（现在进行时被动）；These beautiful pictures have been drawn by my sister since last week.（现在完成时被动）；These books must be returned to the library tomorrow.（情态动词 + be done） 反例：was happened × / is seemed ×（不及物动词、系动词没有被动语态）；The books are sold out last week. ×（last week 要用过去时 were sold） 适用边界：不及物动词与系动词没有被动语态（happen、seem、appear、belong）；“主动表被动”的 6 类情况也不写 be done。by 短语只在强调执行者时保留，否则省略（The window was broken yesterday.）。</p><p><strong>口诀</strong>：被动 = be + done，时态和单复数都写在 be 上 —— 先定 be 的形态（am/is/are/was/were/been/being），再在后面缀上动词的过去分词，时态就不会丢。</p></div><div class="hint-container tip"><p class="hint-container-title">主动表被动 6 条：形式是主动，意思是被动</p><p><strong>句意</strong>：The old building requires repairing. 意思是“这座旧楼需要修缮”；The book sells well. 意思是“这本书很畅销”。</p><p><strong>拆解</strong></p><ul><li>requires repairing：require + doing，主动形式表被动，等于 requires to be repaired</li><li>sells well：sell 与 well 连用，描绘“书本身好卖”这一特性，不用被动</li><li>The problem seems difficult to solve：seem 是系动词，没有被动形式</li><li>I have much work to do：不定式 to do 与 work 是动宾关系，与 I 是主谓关系，用主动表被动</li></ul><p><strong>语法</strong>：主动表被动 6 类：① need/want/require/deserve + doing、be worth doing、not bear doing；② 不定式作定语（work to do、a room to live in）；③ be + adj. + to do（difficult to answer）；④ be to blame 应受责备、be to let 出租；⑤ 系动词 taste、sound、feel、look、smell、prove；⑥ sell、wash、clean、burn、cook 与 well、easily、perfectly 等副词连用。</p><p>正例：The book is worth reading.（值得一读）；I have much work to do.（不定式作定语）；The pen writes smoothly.（笔写起来流畅）；The problem seems difficult to solve.（系动词无被动） 反例：The old building requires to repair. ×（应说 requires repairing 或 requires to be repaired）；The pen is written smoothly. ×（描绘事物特性用主动表被动） 适用边界：只有上述固定的动词和结构才主动表被动，不能推广到所有动词：The window was broken yesterday. 仍是标准被动。不定式作定语时，动词与前面的名词要有动宾关系，介词不能丢（a room to live in）。</p><p><strong>口诀</strong>：need/want/worth 后 doing，系动词无被动，sell well 描特性 —— 看到“需要 / 值得 / 经不住 + 动词”，或动词后面跟着 well、easily 这类副词，先想主动表被动，别急着写 be done。</p></div><div class="hint-container tip"><p class="hint-container-title">被动语态与系表结构：同一个 be + done，两种身份</p><p><strong>句意</strong>：The door was closed by my sister. 意思是“门是我姐姐关的”；The door is now closed. 意思是“门是关着的”。</p><p><strong>拆解</strong></p><ul><li>was closed by my sister：有 by 短语，说的是“被关”这个动作 → 被动语态</li><li>is now closed：没有 by 短语，说的是“门是关着的”这个状态 → 系表结构，closed 相当于形容词</li><li>两者形式都是 be + 过去分词，靠“有没有动作发出者、能不能补出 by”来区分</li></ul><p><strong>语法</strong>：被动语态表动作，可以用在各种时态；系表结构表状态与性质，一般只用于一般现在时和一般过去时。判断方法：能补出 by 短语、能还原成主动句的是被动语态；只描述状态的是系表结构。</p><p>正例：The door was closed by my sister.（被动，有 by 短语）；The door is now closed.（系表，表状态）；These agreements haven&#39;t been signed by the president.（被动，完成时） 反例：把 be interested in 当成被动语态 ×（它是系表结构，表状态）；is seemed × / is felt ×（系动词没有被动形式） 适用边界：问一句“能不能加 by …”：能加、能换成相应主动句的是被动语态；加不上、只说明状态的是系表结构。系表结构一般不用完成时、将来时（She was happy yesterday.）。</p><p><strong>口诀</strong>：有 by、表动作的是被动；没 by、表状态的是系表 —— 顺着“谁做的？”这个问题走：答得出执行者就是被动语态，答不出、只描述样子就是系表结构。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀 · 被动语态的格式<strong>be + done</strong>——be：am / is / are / was / were / been / being；done：动词的过去分词。含义：把主动语态的<strong>宾语变主语</strong>，谓语动词变成 be done。</p><p>他打他的孩子。He beat his kid. → 他的孩子被他打。His kid <strong>was beaten by</strong> him.</p></div><h3 id="各时态下的被动语态" tabindex="-1"><a class="header-anchor" href="#各时态下的被动语态"><span>各时态下的被动语态</span></a></h3><table><thead><tr><th></th><th>一般</th><th>完成</th><th>进行</th></tr></thead><tbody><tr><td><strong>现在</strong></td><td>be done</td><td>have/has been done</td><td>be being done</td></tr><tr><td><strong>过去</strong></td><td>was/were done</td><td>had been done</td><td>was/were being done</td></tr><tr><td><strong>将来</strong></td><td>will be done</td><td>will have been done</td><td>——</td></tr><tr><td><strong>过去将来</strong></td><td>would be done</td><td>——</td><td>——</td></tr></tbody></table><h3 id="_1-被动语态的使用-教材-p100" tabindex="-1"><a class="header-anchor" href="#_1-被动语态的使用-教材-p100"><span>1. 被动语态的使用（教材 P100）</span></a></h3><ol><li>当<strong>不知道</strong>谁是动作的执行者时：The window in the classroom <strong>was broken</strong> yesterday.</li><li>当<strong>不必要说出</strong>动作的执行者时：Evie <strong>was born</strong> in England.</li><li>当动词承受者是叙述对象或<strong>强调动作发出者</strong>时：The thief <strong>was arrested by</strong> the police.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>常见的两种被动句型 （1）<strong>It is/was said/reported/believed/estimated...that...</strong>（据说/据报道/据信/据估计……）：It is reported that less than 20% of these phones end up actually being recycled.</p><p>（2）<strong>sb./sth. + be 动词 + said/reported/believed/estimated + to do</strong>：Mr. Brown is said to have died of liver cancer. 据说布朗先生死于肝癌。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>被动语态的种类 ① <strong>be done</strong>：The window was broken yesterday. 昨天窗户被打碎了。</p><p>② <strong>get + 过去分词</strong>：Five people <strong>got killed</strong> in the explosion. 五个人在这次爆炸中死亡。</p><p>③ <strong>情态动词 + be + 过去分词</strong>：Smoking <strong>can be shown</strong> to increase the possibility of lung cancer.</p></div><h3 id="_2-主动表被动-教材-p101-102-高频" tabindex="-1"><a class="header-anchor" href="#_2-主动表被动-教材-p101-102-高频"><span>2. 主动表被动（教材 P101-102，高频）</span></a></h3><ol><li><strong>need, want, require</strong>（需要），<strong>deserve</strong>（应得），<strong>be worth</strong>（值得），<strong>not bear</strong>（经不住）后接 <strong>doing</strong> 主动表被动：need/want/require/deserve + doing = need/want/require/deserve + <strong>to be done</strong>；be worth doing 值得做某事；not bear doing = not bear being done。</li></ol><p>The old building <strong>requires repairing</strong>. = The old building requires <strong>to be repaired</strong>. / The book <strong>is worth reading</strong>. / The book <strong>can&#39;t bear criticizing</strong>. = The book can&#39;t bear being criticized. 2. <strong>不定式作定语</strong>：与被修饰的名词/代词有<strong>动宾关系</strong>，又在句中与另一名词/代词有<strong>主谓关系</strong>时，用主动表被动：</p><p>I have much work <strong>to do</strong>.（to do 与 work 动宾关系，与 I 主谓关系）</p><p>Tom is looking for a room <strong>to live in</strong>.（与 room 动宾关系，与 Tom 主谓关系） 3. <strong>be + adj. + to do</strong>：The question is difficult <strong>to answer</strong>. / I found the car comfortable <strong>to ride in</strong>. 我觉得这种车很好坐。 4. <strong>be to 结构</strong>中的不定式用主动表被动：<strong>be to blame</strong> 应受责备；<strong>be to let</strong> 出租；<strong>remain to do</strong> 有待去做。 5. <strong>系动词</strong>没有被动形式，但有些常表示被动意义：taste（吃起来）、sound（听起来）、prove（证明是）、feel（摸上去）、look（看起来）、smell（闻起来）：</p><p>Good medicine <strong>tastes</strong> bitter to the mouth. 良药苦口。 6. <strong>sell, wash, clean, burn, cook</strong> 等与 <strong>well, easily, perfectly</strong> 等副词连用，描绘事物特性，主动表被动（主语 + 动词 + 副词）：</p><p>The book <strong>sells well</strong>. 这本书很畅销。</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>拓展 · 被动语态与系表结构的区别</p><ol><li>被动语态中的过去分词<strong>表动作</strong>，是动词；系表结构中的过去分词<strong>表特点、状态或性质</strong>，相当于形容词：</li></ol><p>The door was closed <strong>by my sister</strong>. 门是我姐姐关的。（被动，有 by 短语/动作）</p><p>The door is now <strong>closed</strong>. 门是关着的。（系表，状态）</p><ol start="2"><li>系表结构一般只用于<strong>一般现在时和一般过去时</strong>；被动语态还可用于其它时态：</li></ol><p>These agreements <strong>haven&#39;t been signed</strong> by the president.（被动，完成时）</p><p>She was happy yesterday.（描述过去的状态）</p></div><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 易错清单</p><ul><li><strong>目标</strong>：把本课高频易错点按“时间标志词”重排成一张速查表，让标志词直接指向时态结构。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>时间标志词与高频易错</code></li></ul></div><h3 id="易错清单-·-小步学" tabindex="-1"><a class="header-anchor" href="#易错清单-·-小步学"><span>易错清单 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>时态：时间和动作状态一起看</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>时间标志词速查：看到它，时态就定了</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>高频易错 9 条：临考前再过一遍</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：把“since 点 for 段”“by the time + 过去 → 过去完成”“by + 将来 → 将来完成”三条各配一个例句说出来。</p><div class="hint-container tip"><p class="hint-container-title">时间标志词速查：看到它，时态就定了</p><p><strong>句意</strong>：He will come back in a month. 意思是“他一个月后回来”；In the last 40 years, great changes have taken place in China. 意思是“在过去的 40 年里，中国发生了巨大的变化”。</p><p><strong>拆解</strong></p><ul><li>in a month：in + 将来一段时间，译为“……之后”，配一般将来时</li><li>In the last 40 years：in + 过去的时间段，配现在完成时</li><li>同一个 in，靠后面接的是“将来”还是“过去”决定时态</li><li>since 2010（时间点）与 for ten years（时间段）是现在完成时的一对搭档</li></ul><p><strong>语法</strong>：标志词表：一般现在 always / usually / every day / twice a week；一般过去 yesterday / last week / ago / just now / the other day；一般将来 tomorrow / next year / in a few minutes；现在完成 already / just / yet / never / ever / so far / since + 时间点 / for + 一段时间；过去完成 by the time + 过去时、by the end of + 过去时间；将来完成 by + 将来时间；现在进行 now / right now / at the moment / Look!；过去进行 at that time / at 8 o&#39;clock yesterday / when + 过去时；将来进行 at this time next week。</p><ol><li><strong>一般现在</strong> every day / usually / always——反复的习惯</li><li><strong>一般过去</strong> yesterday / last week / ago / the other day</li><li><strong>现在完成</strong> since 2010 / for ten years / so far / ever</li><li><strong>过去完成</strong> by the time + 过去时 / by the end of last month</li><li><strong>一般将来</strong> tomorrow / next year / in two years</li><li><strong>将来完成</strong> by + 将来时间 / by the end of next year</li></ol><p>正例：They have lived in Beijing since 2010.（since + 时间点 → 现在完成）；We had learned 5000 words by the end of last month.（by the end of + 过去 → 过去完成）；I will have left for London by the time you get to New York.（by + 将来 → 将来完成） 反例：We have learned 5000 words by the end of last month. ×（last month 是过去，应用 had learned）；I don&#39;t know when he comes. ×（宾语从句表将来要用 will come，“主将从现”只管状语从句） 适用边界：同一个词可能有两种身份：in 的将来与过去决定时态；when 引导时间状语从句时用“主将从现”，引导宾语从句时照常可以用将来时。</p><p><strong>口诀</strong>：since 点 for 段；by the time + 过去 → 过去完成；by + 将来 → 将来完成 —— 把标志词抄成一张表，做题先找标志词：标志词负责给时间点，结构负责给动词形态。</p></div><div class="hint-container tip"><p class="hint-container-title">高频易错 9 条：临考前再过一遍</p><p><strong>句意</strong>：I don&#39;t know when he will come. 意思是“我不知道他什么时候来”；It is the first time that I have heard of this news. 意思是“这是我第一次听到这个消息”。</p><p><strong>拆解</strong></p><ul><li>when he will come：when 引导宾语从句，可以用将来时，与“主将从现”不冲突</li><li>It is the first time that I have heard：主句是 is（现在），从句用现在完成时</li><li>若主句改成 It was the first time，从句就要改成 had heard</li></ul><p><strong>语法</strong>：本课高频易错 9 条：① 主将从现（宾语从句不适用）；② since + 时间点 / for + 时间段，非延续性动词不与 for 时段连用；③ have been to 去过（已回）与 have gone to 去了（未回）；④ 先发生用过去完成，后发生用一般过去；⑤ It is the first time that + 现在完成，It was the first time that + 过去完成；⑥ 现在完成（结果）与现在完成进行（持续）；⑦ happen 没有被动语态；⑧ 主动表被动 6 条；⑨ 有 by 短语句、表动作的是被动，表状态的是系表。</p><p>正例：It was the first time that I had encountered such a difficult problem.；The book can&#39;t bear criticizing. = The book can&#39;t bear being criticized. 反例：It is the first time that I heard of this news. ×（主句是 is，从句用 have heard）；was happened × / is seemed ×（不及物动词与系动词没有被动） 适用边界：这些口诀只是“看到标志就优先考虑”的提示，不能替代句意分析：句中没有过去的参照点就不要写过去完成；没有 by 短语但主语是承受者时，仍然可能是被动语态（The window was broken yesterday.）。</p><p><strong>口诀</strong>：“第几次”句型跟着主句的 be 走：is → have done，was → had done —— 主句的 be 动词决定从句用哪一种完成时，就像影子跟着人走。</p></div><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p><strong>主将从现</strong>：if/when/before 引导的时间、条件状语从句用一般现在时（但宾语从句不适用：I don&#39;t know when he <strong>will come</strong>）。</p></li><li><p><strong>since + 时间点 / for + 时间段</strong>是现在完成时标志；<strong>非延续性动词</strong>（buy, die, join 等）不能与 for 时间段连用。</p></li><li><p><strong>have been to 去过（已回）/ have gone to 去了（未回）</strong>。</p></li><li><p><strong>先发生用过去完成时，后发生用一般过去时</strong>；by the time + 过去时 → 主句过去完成时。</p></li><li><p><strong>It is the first time that + 现在完成时</strong>；<strong>It was the first time that + 过去完成时</strong>。</p></li><li><p><strong>现在完成 vs 现在完成进行</strong>：结果 vs 持续。</p></li><li><p><strong>happen 没有被动语态</strong>（was happened ✘）。</p></li><li><p>主动表被动 6 条（need doing / 不定式作定语 / be+adj.+to do / be to blame / 系动词 / sell well 类）——高频考题。</p></li><li><p><strong>被动语态与系表结构</strong>：有 by 短语、表动作的是被动；表状态的是系表。</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>John ____ an English passage every day, so he has a wide vocabulary.</strong></p><ul><li>A. reads</li><li>B. is reading</li><li>C. had read</li><li>D. was reading</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（reads）</strong> —— 原题为教材 P84-85 随堂练习（课件未附答案，笔记补充解析）：every day 习惯性动作用一般现在时，John 三单加 s。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ every day 是习惯性动作的标志 → 一般现在时；主语 John 是第三人称单数，read 加 -s → reads。后一分句 so he has 也是一般现在时，前后一致。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ is reading 是现在进行时，表示“说话时正在读”，与 every day 的习惯义冲突。干扰点：把“经常读书”误当成“此刻正在读”。</li><li>C ❌ had read 是过去完成时，表示“过去的过去”，需要有一个过去的参照点，本句没有。干扰点：见到“读过很多”就联想完成时，却忘了完成时必须有参照时间。</li><li>D ❌ was reading 是过去进行时，既与 every day 的一般性习惯冲突，也与后一分句 has 的时态不一致。干扰点：被 every day 的“过去也读”语感带偏。</li></ul><p><strong>整句翻译</strong>：约翰每天读一篇英语短文，所以他的词汇量很广。</p><p><strong>词组</strong>：<code>every day</code> 每天（一般现在时的频率标志）；<code>an English passage</code> 一篇英语短文；<code>have a wide vocabulary</code> 词汇量大</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·一般现在时时间标志词）：时间标志词：always, usually, every morning/night/evening/day/week/year, often, sometimes, occasionally, from time to time, twice a week</p></details><p><strong>—____ your sister ____ English every day? —Yes, she does.</strong></p><ul><li>A. Do; study</li><li>B. Does; study</li><li>C. Do; studies</li><li>D. Does; studies</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Does; study）</strong> —— 原题为教材 P84-85 随堂练习（笔记补充解析）：疑问句助动词 Does 提前（三单），后面接动词原形 study。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Do 是配 I/you/复数主语的助动词，主语 your sister 是第三人称单数，应用 Does。干扰点：只记住“疑问句用 do”，忘了看人称。</li><li>B ✅ 一般疑问句把助动词提到主语前：your sister 是三单 → Does；助动词后面一律用动词原形 study，答语 Yes, she does 也印证了这一点。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ Do 人称不对，studies 又把三单形式挂在实义动词上——助动词和实义动词不能同时标“三单”。干扰点：不知道三单只需要标一次。</li><li>D ❌ Does 用对了，但助动词后面必须用原形，studies 是第三人称单数形式，等于把“三单”标了两遍。干扰点：把陈述句的 studies 直接搬到疑问句里。</li></ul><p><strong>整句翻译</strong>：——你妹妹每天学英语吗？——是的，她学。</p><p><strong>词组</strong>：<code>every day</code> 每天；<code>Does … study</code> 一般现在时的一般疑问句：助动词 Does 提前，其后用动词原形</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·什么是第三人称单数）：主语非 I、非 you、非复数，就是第三人称单数。</p></details><p><strong>They will hold a party if they ____ the project on time.</strong></p><ul><li>A. will complete</li><li>B. complete</li><li>C. completed</li><li>D. had completed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（complete）</strong> —— 原题为教材 P84-85 随堂练习（笔记补充解析）：主将从现——if 条件状语从句用一般现在时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ if 条件状语从句里不用将来时。干扰点：主句是 will hold，就把将来时照抄到从句里。</li><li>B ✅ 主将从现：主句 They will hold 用一般将来时，if 条件状语从句用一般现在时表将来 → complete（主语 they 用原形）。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ completed 一般过去时，与“将来要办聚会”的时间指向矛盾。干扰点：看到“完成项目”就联想过去。</li><li>D ❌ had completed 是过去完成时，需要过去的参照点，本句的时间指向将来。干扰点：把“先完成”误解为“过去的过去”。</li></ul><p><strong>整句翻译</strong>：如果他们按时完成这个项目，他们就举办聚会。</p><p><strong>词组</strong>：<code>hold a party</code> 举办聚会；<code>on time</code> 按时，准时</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·主将从现）：主将从现（时间/条件状语从句中，主句用一般将来时，从句用一般现在时）</p></details><p><strong>【24湖南真题】The plane ______ on time yesterday, but traffic was awful.</strong></p><ul><li>A. arrives</li><li>B. arrived</li><li>C. had arrived</li><li>D. has arrived</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（arrived）</strong> —— yesterday 是一般过去时标志词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ arrives 是一般现在时，与 yesterday 这一明确的过去时间冲突。</li><li>B ✅ yesterday 是一般过去时标志词 → arrived；but 后一分句的 was 也是过去时，两句时态一致。</li><li>C ❌ had arrived 是过去完成时，必须有“过去的过去”作参照，本句只交代了一个过去时间点。干扰点：把“更早到达”的错觉当成第二个过去动作。</li><li>D ❌ has arrived 是现在完成时，不能与 yesterday 这类明确过去时间状语连用。干扰点：把“已经到达”的中文语感套成完成时。</li></ul><p><strong>整句翻译</strong>：飞机昨天准时到达，但交通很糟糕。</p><p><strong>词组</strong>：<code>on time</code> 准时；<code>traffic was awful</code> 交通很糟糕（was 是过去式，与 arrived 呼应）</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·真题例）：真题例：The plane arrived on time yesterday, but traffic was awful.【24湖南】</p></details><p><strong>He ____ by his sister at that moment.</strong></p><ul><li>A. happened to see</li><li>B. was happened to see</li><li>C. was happened to be seen</li><li>D. happened to be seen</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（happened to be seen）</strong> —— 原题为教材 P86 补充练习（笔记补充解析）：happen 是不及物动词，没有被动语态（排除 B/C）；&quot;他碰巧被姐姐看到&quot;用 happen to be seen；at that moment 过去时 → happened。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ happened to see 少了被动这一层：“他”是“被”看到的，see 的执行者是姐姐。干扰点：只顾给 happen 变过去式，漏掉 see 与主语的被动关系。</li><li>B ❌ was happened 不成立：happen 是不及物动词，没有被动语态。干扰点：把“碰巧”当成一个可以被动的动作。</li><li>C ❌ 两处都错：was happened 本身不合法；后面的 to see 也没有体现“被看到”。</li><li>D ✅ happen 用主动形式（不及物动词没有被动），at that moment 提示过去 → happened；“被姐姐看到”用不定式的被动式 to be seen，合起来 happened to be seen。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：当时他碰巧被姐姐看到了。</p><p><strong>词组</strong>：<code>happen to do sth.</code> 碰巧做某事（happen 是不及物动词，没有被动语态）；<code>at that moment</code> 在那时（过去时间标志）；<code>to be seen</code> 被看到（不定式的被动式，说明主语是承受者）</p><p><strong>对比自测</strong>：做完后对照 quiz:33，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·易错清单）：happen 没有被动语态（was happened ✘）</p></details><p><strong>I ____ to the park yesterday and ____ a lot of beautiful flowers.</strong></p><ul><li>A. go; see</li><li>B. went; saw</li><li>C. goes; sees</li><li>D. going; seeing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（went; saw）</strong> —— 原题为教材 P86 补充练习（笔记补充解析）：yesterday 用一般过去时 went; saw。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ go; see 是一般现在时（表习惯），与 yesterday 的过去时间冲突。</li><li>B ✅ 两个并列谓语都发生在昨天 → 都用一般过去式 went; saw；并列谓语的时态必须一致。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ goes; sees 是三单一般现在时，主语是 I，连人称都对不上。</li><li>D ❌ going; seeing 是分词/动名词这类非谓语形式，句子会没有谓语，两个并列动作也不能这样写。</li></ul><p><strong>整句翻译</strong>：我昨天去了公园，看到了许多美丽的花。</p><p><strong>词组</strong>：<code>go to the park</code> 去公园；<code>a lot of beautiful flowers</code> 许多美丽的花</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·一般过去时时间标志词）：时间标志词：yesterday (morning/afternoon/evening), the day before yesterday, last night (week, Sunday, weekend), ago …</p></details><p><strong>____ you ____ to the party last weekend?</strong></p><ul><li>A. Do; go</li><li>B. Did; went</li><li>C. Did; go</li><li>D. Will; go</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Did; go）</strong> —— 原题为教材 P86 补充练习组（笔记补充解析）：Did 后接动词原形 go。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Do; go 是一般现在时，与 last weekend 冲突。</li><li>B ❌ Did; went 把过去标了两遍：助动词 Did 已经承担了“过去”，后面必须用原形 go。干扰点：把陈述句里的 went 直接搬进疑问句。</li><li>C ✅ last weekend 是过去时间 → 一般疑问句把助动词 Did 提前；助动词后面用动词原形 → Did you go…。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ Will; go 是将来时，与过去时间状语 last weekend 矛盾。</li></ul><p><strong>整句翻译</strong>：上周末你去参加聚会了吗？</p><p><strong>词组</strong>：<code>last weekend</code> 上周末（过去时间标志）；<code>go to the party</code> 去参加聚会</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·易错清单（原题 why））：Did 后接动词原形 go。原题为教材 P86 补充练习组（笔记补充解析）。</p></details><p><strong>He ____ very happy when he received the gift.</strong></p><ul><li>A. is</li><li>B. was</li><li>C. were</li><li>D. will be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（was）</strong> —— 原题为教材 P86 补充练习组（笔记补充解析）：he 单数、when he received 过去背景 → was。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is 是一般现在时，与 when he received（过去）的时间背景冲突。</li><li>B ✅ when 从句用 received（过去），主句说的是当时的状态 → was；主语 he 是单数。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 是复数或第二人称的过去式，与单数主语 he 不一致。干扰点：只记得“过去用过去式”，忘了看主语的数。</li><li>D ❌ will be 是将来时，与过去时间背景冲突。</li></ul><p><strong>整句翻译</strong>：收到礼物时他非常高兴。</p><p><strong>词组</strong>：<code>receive the gift</code> 收到礼物；<code>be happy</code> 高兴（此处 be 作系动词，表状态）</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·一般过去时含义）：过去某个时间里发生的动作或状态；过去习惯性、经常性的动作或行为。</p></details><p><strong>【25湖南真题】The city ______ a bridge across the river next year.</strong></p><ul><li>A. build</li><li>B. built</li><li>C. has built</li><li>D. will build</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（will build）</strong> —— next year 是一般将来时标志词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ build 与主语 The city 的数不一致（三单该用 builds），也没有将来意味。</li><li>B ❌ built 是一般过去时，与 next year 这一将来时间冲突。</li><li>C ❌ has built 是现在完成时，不能与表示将来的 next year 连用。干扰点：was 建成、已经建成的中文语感让人误用完成时。</li><li>D ✅ next year 是一般将来时标志词 → will build（主语 The city 与 will 不冲突）。</li></ul><p><strong>整句翻译</strong>：这座城市明年将在河上建一座桥。</p><p><strong>词组</strong>：<code>across the river</code> 横跨这条河；<code>next year</code> 明年（一般将来时标志）</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·一般将来时时间标志词）：时间标志词：tomorrow, next day (week, month, year...), soon, in a few minutes, the day after tomorrow。</p></details><p><strong>练1：Hurry up, children! The school bus ____ for us.</strong></p><ul><li>A. waits</li><li>B. is waiting</li><li>C. waited</li><li>D. was waiting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is waiting）</strong> —— 原题为教材 P88 练习题（笔记补充解析）：Hurry up 提示此刻正在等 → 现在进行时 is waiting。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ waits 是一般现在时，表示平时的习惯，而 Hurry up 的语境是“此刻正在等”。干扰点：把当下情境当成一般事实。</li><li>B ✅ Hurry up 提示说话时正在发生 → 现在进行时；主语 the school bus 是单数 → is waiting。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ waited 是一般过去时，与此刻的催促情境冲突。</li><li>D ❌ was waiting 是过去进行时，句子没有过去时间参照，也不合催促的语境。</li></ul><p><strong>整句翻译</strong>：快点，孩子们！校车在等我们。</p><p><strong>词组</strong>：<code>Hurry up!</code> 快点！（提示此刻的紧迫情境）；<code>wait for sb.</code> 等某人</p><p><strong>对比自测</strong>：做完后对照 quiz:12，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·现在进行时时间标志词）：时间标志词：now, this week, right now, just now, at the moment, at present，look, listen, smell 等。</p></details><p><strong>练2：Look! The children ____ in the park.</strong></p><ul><li>A. play</li><li>B. plays</li><li>C. played</li><li>D. are playing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（are playing）</strong> —— 原题为教材 P88 练习题（笔记补充解析）：Look! 提示正在进行。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ play 是一般现在时表习惯，与 Look! 的即时提示不符。</li><li>B ❌ plays 是三单形式，主语 children 是复数，本身就矛盾。</li><li>C ❌ played 是过去时，与 Look! 冲突。</li><li>D ✅ Look! 是现在进行时的提示词；主语 the children 是复数 → are playing。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：看！孩子们正在公园里玩。</p><p><strong>词组</strong>：<code>Look!</code> 看！（现在进行时的提示词，提示眼前正在发生）；<code>in the park</code> 在公园里</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·现在进行时用法）：表示说话时正在进行的动作或发生的事情：We are waiting for you.</p></details><p><strong>练3：____ you ____ dinner now?</strong></p><ul><li>A. Do; cook</li><li>B. Are; cooking</li><li>C. Did; cook</li><li>D. Will; cook</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Are; cooking）</strong> —— 原题为教材 P88 练习题（笔记补充解析）：now 提示现在进行时 Are; cooking。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Do; cook 是一般现在时，问的是平时的习惯，与 now 冲突。</li><li>B ✅ now 提示现在进行时；一般疑问句把 be 动词提前 → Are you cooking…? 动词用 -ing 形式。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ Did; cook 是过去时，与 now 冲突。</li><li>D ❌ Will; cook 是将来时，与 now 冲突。</li></ul><p><strong>整句翻译</strong>：你现在正在做晚饭吗？</p><p><strong>词组</strong>：<code>cook dinner</code> 做晚饭；<code>now</code> 现在（现在进行时标志）</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·现在进行时结构）：结构：主语 + be (am/is/are) + doing + 其他。</p></details><p><strong>练4：He ____ for the test these days.</strong></p><ul><li>A. studies</li><li>B. studied</li><li>C. is studying</li><li>D. will study</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（is studying）</strong> —— 原题为教材 P88 练习题（笔记补充解析）：these days 表示现阶段进行之中的动作。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ studies 是一般现在时，表示长期习惯，与 these days 强调的“现阶段持续推进”不符。干扰点：把这些天当成长期习惯。</li><li>B ❌ studied 是过去时，与 these days 的时间指向冲突。</li><li>C ✅ these days 表示现阶段正处于进行之中的动作 → 现在进行时；主语 He 单数 → is studying。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ will study 是将来时，改变了句意（变成“将要去复习”）。</li></ul><p><strong>整句翻译</strong>：这些天他一直在为考试复习。</p><p><strong>词组</strong>：<code>these days</code> 这些天（表示现阶段正在进行）；<code>study for the test</code> 为考试复习</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·现在进行时用法）：表示现阶段处于进行之中的动作，但说话时不一定正在进行</p></details><p><strong>练习1：At 8 o’clock yesterday, she ____ a shower.</strong></p><ul><li>A. takes</li><li>B. took</li><li>C. is taking</li><li>D. was taking</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（was taking）</strong> —— 原题为教材 P89 练习题（笔记补充解析）：过去某时刻正在发生 → 过去进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ takes 是一般现在时，与过去时间冲突。</li><li>B ❌ took 是一般过去时，表示“洗完了”；At 8 o&#39;clock yesterday 说的是“那一点正在洗”。干扰点：把“某时刻正在做”简化成一般过去。</li><li>C ❌ is taking 是现在进行时，时间不对。</li><li>D ✅ At 8 o&#39;clock yesterday 是“过去某一时刻”的标志 → 过去进行时；主语 she 单数 → was taking。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：昨天 8 点她正在洗澡。</p><p><strong>词组</strong>：<code>take a shower</code> 洗澡；<code>at 8 o&#39;clock yesterday</code> 昨天 8 点（过去的某一时刻）</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·过去进行时时间标志词）：时间标志词：at this time yesterday, at that time, the whole morning, all day yesterday, from January to March last year，或 when 引导的谓语动词为一般过去时的时间状语等。</p></details><p><strong>练习2：____ they ____ TV when I called?</strong></p><ul><li>A. Do; watch</li><li>B. Did; watch</li><li>C. Were; watching</li><li>D. Will; watch</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Were; watching）</strong> —— 原题为教材 P89 练习题（笔记补充解析）：when I called 为过去背景，&quot;正在看电视&quot;用过去进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Do; watch 是一般现在时，与 when I called 的过去背景冲突。</li><li>B ❌ Did; watch 是一般过去时，问的是“看没看”，而句意是“正在看”。干扰点：只注意到过去，忽略了进行。</li><li>C ✅ when I called 给出过去时间背景，“正在看电视”用过去进行时；疑问句把 were 提前，主语 they 复数 → Were they watching…?来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ Will; watch 是将来时，与过去背景冲突。</li></ul><p><strong>整句翻译</strong>：我打电话的时候，他们正在看电视吗？</p><p><strong>词组</strong>：<code>when I called</code> 我打电话的时候（过去时间背景）；<code>watch TV</code> 看电视</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·过去进行时与一般过去时互为时间背景）：结构：主语 1 + was/were doing，when + 主语 2 + did...</p></details><p><strong>练习3：We ____ football on the playground at that time.</strong></p><ul><li>A. play</li><li>B. played</li><li>C. are playing</li><li>D. were playing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（were playing）</strong> —— 原题为教材 P89 练习题（笔记补充解析）：at that time 过去某段时间正在进行。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ play 是一般现在时，与 at that time 的时间指向冲突。</li><li>B ❌ played 是一般过去时，强调动作完成，与“那段时间正在踢”的持续义不符。</li><li>C ❌ are playing 是现在进行时，时间不对。</li><li>D ✅ at that time 指过去某段时间正在进行 → 过去进行时；主语 We 是复数 → were playing。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：那时我们正在操场上踢足球。</p><p><strong>词组</strong>：<code>at that time</code> 那时（过去某段时间）；<code>on the playground</code> 在操场上</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·过去进行时含义）：含义：表示过去某段时间或某一时刻正在发生或进行的行为或动作。</p></details><p><strong>At this time next week, we ____ the matter with our friends.</strong></p><ul><li>A. are going to discuss</li><li>B. will be discussing</li><li>C. are discussing</li><li>D. are to discuss</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（will be discussing）</strong> —— 课件附解析：at this time 提示用进行时，next week 提示将来时 → 将来进行时。本句意为：下周的这个时候，我们将与我们的朋友讨论这个问题。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are going to discuss 只表“打算”，不表“下周这个时候正在讨论”。干扰点：把“将来”一律交给 be going to。</li><li>B ✅ at this time 提示进行时，next week 提示将来 → 将来进行时 will be discussing，正好表示将来某时刻正在做的事。</li><li>C ❌ are discussing 是现在进行时，时间不对。</li><li>D ❌ are to discuss 表示按约定、安排要做的事，不表示“正在做”。</li></ul><p><strong>整句翻译</strong>：下周的这个时候，我们将正在与朋友们讨论这件事。</p><p><strong>词组</strong>：<code>at this time next week</code> 下周这个时候（将来的某一时刻）；<code>discuss the matter with sb.</code> 与某人讨论这件事</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：at this time 提示用进行时，next week 提示将来时 → 将来进行时。</p></details><p><strong>I ____ this movie three times.</strong></p><ul><li>A. saw</li><li>B. have seen</li><li>C. see</li><li>D. am seeing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（have seen）</strong> —— 课件附答案解析：&quot;次数&quot;（three times）是现在完成时典型用法，强调&quot;累计经历&quot;。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ saw 是一般过去时，只能说明某一次过去看了，无法表达“到今天为止累计三遍”。干扰点：把“看过”一律当过去。</li><li>B ✅ 次数（three times）是现在完成时的典型用法，强调从过去到现在的累计经历；主语 I → have seen。</li><li>C ❌ see 是一般现在时，不能表示累计经历。</li><li>D ❌ am seeing 是现在进行时，表示此刻正在看，语义完全变了。</li></ul><p><strong>整句翻译</strong>：这部电影我看过三遍。</p><p><strong>词组</strong>：<code>three times</code> 三次（累计经历，现在完成时典型用法）</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：“次数”（three times）是现在完成时典型用法，强调“累计经历”。</p></details><p><strong>They ____ in Beijing since 2010.</strong></p><ul><li>A. lived</li><li>B. have lived</li><li>C. are living</li><li>D. will live</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（have lived）</strong> —— 课件附答案解析：&quot;since + 时间点&quot;是现在完成时标志。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ lived 是一般过去时，表示“过去住过”，不能表达一直住到现在。</li><li>B ✅ since + 时间点（2010）是现在完成时标志，表示从过去持续到现在；主语 They → have lived。</li><li>C ❌ are living 是现在进行时，不能与 since 连用表示“从那时持续到现在”。</li><li>D ❌ will live 是将来时，改变了句意。</li></ul><p><strong>整句翻译</strong>：他们从 2010 年起就住在北京。</p><p><strong>词组</strong>：<code>since + 时间点</code> 自从……（现在完成时的标志）；<code>live in Beijing</code> 住在北京</p><p><strong>对比自测</strong>：做完后对照 quiz:28，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：“since + 时间点”是现在完成时标志。</p></details><p><strong>____ you ever ____ to Japan?</strong></p><ul><li>A. Have…been</li><li>B. Did…go</li><li>C. Are…going</li><li>D. Will…go</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（Have…been）</strong> —— 课件附答案解析：&quot;ever&quot;是现在完成时标志词，强调&quot;经历&quot;。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ ever（曾经）是现在完成时标志词，强调经历；have been to 表示“去过（人已回来）”，疑问句把 Have 提到句首。</li><li>B ❌ Did…go 是一般过去时，问的是某一次具体的过去经历，与 ever 的“至今有没有过”不搭。干扰点：把“去过”当成纯粹的过去事件。</li><li>C ❌ Are…going 是现在进行时，问的是“正在去”，语义不符。</li><li>D ❌ Will…go 是将来时，问的是“要不要去”，语义不符。</li></ul><p><strong>整句翻译</strong>：你去过日本吗？</p><p><strong>词组</strong>：<code>have been to</code> 去过某地（现在已经回来）；<code>ever</code> 曾经（现在完成时的经历标志）</p><p><strong>对比自测</strong>：做完后对照 quiz:18，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：“ever”是现在完成时标志词，强调“经历”。</p></details><p><strong>We ____ finished our assignment when the teacher came to the classroom.</strong></p><ul><li>A. had just</li><li>B. have just</li><li>C. just had</li><li>D. just have</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（had just）</strong> —— 原题为教材 P96 随堂练习（笔记补充解析）：&quot;老师来教室&quot;是过去，&quot;完成作业&quot;在其之前 → 过去的过去，had just finished。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ “老师来教室”是过去，“完成作业”发生在它之前 → 过去的过去，用过去完成时；just 的位置在助动词后、过去分词前：had just finished。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ have just 是现在完成时，与 when the teacher came 的过去背景冲突。干扰点：把“刚刚完成”直接译成现在完成时。</li><li>C ❌ just had 把 just 放到了 had 之前，语序不合（just 常紧跟助动词之后）；而且 had 在前才能构成过去完成时结构。</li><li>D ❌ just have 是现在完成时的语序错误形式，时态本身也不对。</li></ul><p><strong>整句翻译</strong>：老师走进教室时，我们刚刚完成作业。</p><p><strong>词组</strong>：<code>finish one&#39;s assignment</code> 完成作业；<code>had just done</code> 刚刚做完（just 放在助动词 had 与过去分词之间）</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·无时间状语时）：两个动作均发生在过去：先发生的动作用过去完成时，后发生的动作用一般过去时。</p></details><p><strong>By the time I got to the station, the train ____.</strong></p><ul><li>A. left</li><li>B. has left</li><li>C. had left</li><li>D. leaves</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had left）</strong> —— 原题为教材 P96 随堂练习（笔记补充解析）：By the time + 过去时，主句用过去完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ left 是一般过去时，无法表达“在我到达之前就已经开走”这一先后关系。干扰点：两个过去动作都写成过去式，先后丢失。</li><li>B ❌ has left 是现在完成时，与 by the time 从句的过去时间冲突。</li><li>C ✅ by the time + 一般过去时 → 主句用过去完成时，表示“到那时之前已经完成”：had left。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ leaves 是一般现在时，与过去语境冲突。</li></ul><p><strong>整句翻译</strong>：我到达车站时，火车已经开走了。</p><p><strong>词组</strong>：<code>by the time</code> 到……的时候（引导时间状语从句）；<code>get to the station</code> 到达车站</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·易错清单）：先发生用过去完成时，后发生用一般过去时；by the time + 过去时 → 主句过去完成时。</p></details><p><strong>She said that she ____ the book twice.</strong></p><ul><li>A. read</li><li>B. has read</li><li>C. had read</li><li>D. reads</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had read）</strong> —— 原题为教材 P96 随堂练习（笔记补充解析）：宾语从句中主句 said 是过去，&quot;读两次&quot;发生在&quot;说&quot;之前 → 过去完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ read 是一般过去时，无法体现“读”发生在“说”之前。干扰点：两个动作都用过去式，先后关系丢失。</li><li>B ❌ has read 是现在完成时，不能出现在 said 之后的宾语从句里（时态要呼应）。</li><li>C ✅ 主句 said 是过去时，“读两遍”发生在“说”之前 → 宾语从句用过去完成时 had read。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ reads 是一般现在时，与主句过去时冲突。</li></ul><p><strong>整句翻译</strong>：她说这本书她读过两遍。</p><p><strong>词组</strong>：<code>read the book twice</code> 读过这本书两遍；<code>宾语从句时态呼应</code> 主句是过去时，从句用相应的过去时态</p><p><strong>对比自测</strong>：做完后对照 quiz:31，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·过去完成时用法（原题 why））：宾语从句中主句 said 是过去，“读两次”发生在“说”之前 → 过去完成时。</p></details><p><strong>填空转选择（笔记补充练习）：When I came into the classroom, my dear students ______ (begin) reading.</strong></p><ul><li>A. began</li><li>B. have begun</li><li>C. had begun</li><li>D. were beginning</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had begun）</strong> —— 原题为填空题，笔记答案 had begun：无时间状语时，两个过去动作中先发生的用过去完成时（&quot;过去的过去&quot;）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ began 是一般过去时，无法表达“在我进来之前已经开始”。</li><li>B ❌ have begun 是现在完成时，与 came 的过去背景冲突。</li><li>C ✅ 没有时间状语时，两个过去动作中先发生的用过去完成时：begin 先于 came → had begun。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ were beginning 是过去进行时，语义是“我进来时恰好开始”，与“已经开始”不符。干扰点：把“正在进行”当成“已经完成”。</li></ul><p><strong>整句翻译</strong>：我走进教室时，我亲爱的同学们已经开始朗读了。</p><p><strong>词组</strong>：<code>come into the classroom</code> 走进教室；<code>begin doing sth.</code> 开始做某事（begin 的分词变化为 begin-began-begun）</p><p><strong>对比自测</strong>：做完后对照 quiz:20，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·例句）：When I came into the classroom, my dear students had begun reading.</p></details><p><strong>By the time you get to New York, I ____ for London.</strong></p><ul><li>A. would be leaving</li><li>B. am leaving</li><li>C. have already left</li><li>D. will have left</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（will have left）</strong> —— 课件附答案 D：by the time + 将来语境 → 将来完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ would be leaving 是过去将来进行时，句子没有过去背景。</li><li>B ❌ am leaving 只表示“正在（即将）离开”，不能表达“到那时已经离开”。</li><li>C ❌ have already left 是现在完成时，与“你到纽约时”这一将来时间点冲突。</li><li>D ✅ by the time 从句用一般现在时表将来 → 主句是将来；动作在这一将来时间之前完成 → 将来完成时 will have left。</li></ul><p><strong>整句翻译</strong>：等你到纽约时，我将已经动身去伦敦了。</p><p><strong>词组</strong>：<code>by the time you get to New York</code> 等你到达纽约时（从句用一般现在时表将来）；<code>leave for</code> 动身前往（leave for London 动身去伦敦）</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·将来完成时）：时间标志词：by the time of + 将来的时间；by + 将来的时间。</p></details><p><strong>【22重庆真题改编（假设说话时点为2021年）】They got married in 1992 and ____ for 30 years by 2022.</strong></p><ul><li>A. will be married</li><li>B. get married</li><li>C. will have been married</li><li>D. were married</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（will have been married）</strong> —— 本题为真题改编，明确将说话时点设为2021年；by 2022 表示将来完成时点，故用 will have been married。若改成当前回顾语境，应改为 had been married，不能沿用原答案。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will be married 只表“将要结婚”这一状态，不能表达“到那时已经 30 年”。</li><li>B ❌ get married 是一般现在时，与 1992 / 2022 的时间线都对不上。</li><li>C ✅ 本题明确把说话时点设为 2021 年，by 2022 是将来时间点 → 将来完成时 will have been married；be married 是状态，所以用 be 的完成形式 been。</li><li>D ❌ were married 是一般过去时，与 by 2022 的“到那时为止”不符。</li></ul><p><strong>整句翻译</strong>：他们 1992 年结婚，到 2022 年就已经结婚 30 年了。</p><p><strong>词组</strong>：<code>by 2022</code> 到 2022 年为止（by + 将来时间）；<code>be married for 30 years</code> 结婚 30 年（be married 表状态）</p><p><strong>对比自测</strong>：做完后对照 quiz:29，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：本题为真题改编，明确将说话时点设为2021年；by 2022 表示将来完成时点，故用 will have been married。若改成当前回顾语境，应改为 had been married，不能沿用原答案。</p></details><p><strong>时态随堂填空转选择（课件附答案）：By the time I walked into the classroom, the teacher ______ (start) teaching.</strong></p><ul><li>A. started</li><li>B. has started</li><li>C. had started</li><li>D. was starting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had started）</strong> —— 原题为填空题，笔记答案 had started：By the time + 过去时 → 主句过去完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ started 是一般过去时，无法表达“已经先开始”。</li><li>B ❌ has started 是现在完成时，与过去背景冲突。</li><li>C ✅ By the time + 一般过去时（walked）→ 主句用过去完成时 had started，表示在“我走进教室”之前就已经开始。</li><li>D ❌ was starting 是过去进行时，指“正在开始”，与“已经开始”不符。</li></ul><p><strong>整句翻译</strong>：我走进教室时，老师已经开始讲课了。</p><p><strong>词组</strong>：<code>walk into the classroom</code> 走进教室；<code>start doing sth.</code> 开始做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·易错清单（原题 why））：原题为填空题，笔记答案 had started：By the time + 过去时 → 主句过去完成时。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>时态随堂填空转选择（课件附答案）：What ______ his mother ______ (do) when he opened the door?</strong></p><ul><li>A. did; do</li><li>B. was; doing</li><li>C. is; doing</li><li>D. has; done</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（was; doing）</strong> —— 原题为填空题，笔记答案 was doing：open the door 过去时刻正在进行的动作 → 过去进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ did; do 是一般过去时，问的是“做了什么”，与“开门那一刻正在做什么”不符。干扰点：把疑问句的 did 当成万能助动词。</li><li>B ✅ when he opened the door 是过去时间点，问那一刻正在进行的动作 → 过去进行时；疑问词 What + was + 主语 + doing。</li><li>C ❌ is; doing 是现在进行时，与 he opened 的过去背景冲突。</li><li>D ❌ has; done 是现在完成时，问的是“已经做了什么”，时态与语义都不合。</li></ul><p><strong>整句翻译</strong>：他开门的时候，他妈妈正在做什么？</p><p><strong>词组</strong>：<code>open the door</code> 开门；<code>What was sb. doing…?</code> （过去某时）某人正在做什么？（过去进行时的疑问句式）</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·过去进行时含义（原题 why））：原题为填空题，笔记答案 was doing：open the door 过去时刻正在进行的动作 → 过去进行时。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>时态随堂填空转选择（课件附答案）：Tom ______ (work) there since two years ago.</strong></p><ul><li>A. worked</li><li>B. has worked</li><li>C. works</li><li>D. had worked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（has worked）</strong> —— 原题为填空题，笔记答案 has worked / has been working：since two years ago 现在完成（进行）时，选项 B 正确。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ worked 是一般过去时，不能表达一直持续到现在。</li><li>B ✅ since + 一段时间 + ago 是现在完成（进行）时标志；主语 Tom 三单 → has worked（原题答案是 has worked / has been working，选项里只有 has worked）。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ works 是一般现在时，只说明目前的习惯状态，不表“从两年前持续至今”。</li><li>D ❌ had worked 是过去完成时，需要一个过去的参照点，本句没有。</li></ul><p><strong>整句翻译</strong>：汤姆从两年前起就在那里工作了。</p><p><strong>词组</strong>：<code>since + 一段时间 + ago</code> 自从……以前起（since 的三种接法之一）；<code>work there</code> 在那里工作</p><p><strong>对比自测</strong>：做完后对照 quiz:18，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·since 的三种接法）：① since + 过去时间点；② since + 一段时间 + ago；③ since + 句子。The team has practiced daily since a week ago.</p></details><p><strong>时态随堂填空转选择（课件附答案）：We ______ (learn) 5000 words by the end of last month.</strong></p><ul><li>A. learned</li><li>B. have learned</li><li>C. had learned</li><li>D. will have learned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had learned）</strong> —— 原题为填空题，笔记答案 had learned：by the end of last month 过去时间点之前完成 → 过去完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ learned 是一般过去时，缺少“到那时为止已完成”的完成义。干扰点：见到 last month 就直接用过去式。</li><li>B ❌ have learned 是现在完成时，与 by the end of last month 的过去时间冲突。</li><li>C ✅ by the end of + 过去时间 → 主句用过去完成时 had learned，表示在那个过去时间点之前已经完成。</li><li>D ❌ will have learned 是将来完成时，与过去时间 last month 冲突。</li></ul><p><strong>整句翻译</strong>：到上个月月底为止，我们已经学了 5000 个单词。</p><p><strong>词组</strong>：<code>by the end of last month</code> 到上个月月底为止（过去的时间点）；<code>learn 5000 words</code> 学会 5000 个单词</p><p><strong>对比自测</strong>：做完后对照 quiz:24，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·易错清单（原题 why））：原题为填空题，笔记答案 had learned：by the end of last month 过去时间点之前完成 → 过去完成时。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>时态随堂填空转选择（课件附答案）：The song ______ (sing) for two hours.</strong></p><ul><li>A. has sung</li><li>B. has been sung</li><li>C. is sung</li><li>D. sang</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（has been sung）</strong> —— 原题为填空题，笔记答案 has been sung：被动 + 完成（进行）意味，for two hours 完成时标志。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has sung 是主动语态：歌不会自己唱，sing 的主语应该是人。干扰点：只盯着完成时，忘了判语态。</li><li>B ✅ 歌是“被”唱的 → 被动 been sung；for two hours 是完成时标志 → has been sung（现在完成时的被动式）。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ is sung 是一般现在时被动，不能表达持续两小时。</li><li>D ❌ sang 是主动的过去式，语态和时态都不对。</li></ul><p><strong>整句翻译</strong>：这首歌已经被唱了两个小时了。</p><p><strong>词组</strong>：<code>for two hours</code> 持续两小时（完成时标志）；<code>has been sung</code> 已经被唱（现在完成时的被动式）</p><p><strong>对比自测</strong>：做完后对照 quiz:46，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：现在 / 完成：have/has been done</p></details><p><strong>时态随堂填空转选择（课件附答案）：The children learned that autumn ______ (be) the season of falling leaves.</strong></p><ul><li>A. was</li><li>B. is</li><li>C. were</li><li>D. would be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：客观真理不受主句时态影响。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ was 顺着“主句过去，从句也过去”的呼应思路走，但“秋天是落叶的季节”是客观真理。干扰点：机械套用宾语从句的时态呼应。</li><li>B ✅ 客观真理、科学事实不受主句时态影响，仍用一般现在时；主语 autumn 是单数 → is。</li><li>C ❌ were 既数不对（autumn 单数），也仍是过去时。</li><li>D ❌ would be 是过去将来时，与客观真理冲突。</li></ul><p><strong>整句翻译</strong>：孩子们知道秋天是落叶的季节。</p><p><strong>词组</strong>：<code>learn that…</code> 了解到……（learn 的过去式为 learned）；<code>falling leaves</code> 落叶</p><p><strong>对比自测</strong>：做完后对照 quiz:22，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·一般现在时用法（原题 why））：原题为填空题，笔记答案 is：客观真理不受主句时态影响。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>语态随堂练习（教材 P100，笔记补充解析）：The new bridge ____ last month.</strong></p><ul><li>A. was built</li><li>B. is built</li><li>C. built</li><li>D. builds</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（was built）</strong> —— last month 过去时间 + 桥&quot;被&quot;建 → 一般过去时被动 was built。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ last month 是过去时间，桥是“被”建的 → 一般过去时的被动式 was built。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ is built 是一般现在时被动，与 last month 冲突。干扰点：看到桥的现状就用了现在时。</li><li>C ❌ built 是主动语态，桥不能自己建造。干扰点：只按时态选了过去式，忘了判语态。</li><li>D ❌ builds 是主动的一般现在时，语态与时态都不对。</li></ul><p><strong>整句翻译</strong>：这座新桥是上个月建成的。</p><p><strong>词组</strong>：<code>last month</code> 上个月（一般过去时标志）；<code>be built</code> 被建造（一般过去时的被动式 was/were built）</p><p><strong>对比自测</strong>：做完后对照 quiz:38，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：过去 / 一般：was/were done</p></details><p><strong>语态随堂练习（教材 P100，笔记补充解析）：—What happened to Billy? —He ____ because of his drink-driving.</strong></p><ul><li>A. is caught</li><li>B. was caught</li><li>C. has caught</li><li>D. had caught</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（was caught）</strong> —— 他&quot;被&quot;抓，且问句 happened 提示过去 → was caught。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is caught 是一般现在时被动，与问句 happened 的过去时间冲突。</li><li>B ✅ 问句 happened 提示过去；“他”是“被”抓的 → was caught。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ has caught 是主动的现在完成时：catch 后面缺宾语，语态与时态都不对。干扰点：忘了“被抓”必须用被动。</li><li>D ❌ had caught 是主动的过去完成时，既无被动也无参照点。</li></ul><p><strong>整句翻译</strong>：——比利出了什么事？——他因为酒后驾车被抓了。</p><p><strong>词组</strong>：<code>drink-driving</code> 酒后驾车；<code>be caught</code> 被抓（被动语态）</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·易错清单）：happen 没有被动语态（was happened ✘）</p></details><p><strong>语态随堂练习（教材 P103，笔记补充解析）：The cloth ____ very soft and comfortable.</strong></p><ul><li>A. feels</li><li>B. is felt</li><li>C. is feeling</li><li>D. felt</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（feels）</strong> —— feel 是系动词，主动表被动；描述面料特性用一般现在时。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ feel 是系动词，主动形式表被动意义（“摸起来”）；描述事物特性用一般现在时 → feels。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ is felt 不成立：系动词没有被动语态。干扰点：以为“被摸”就该用被动。</li><li>C ❌ is feeling 是进行时：系动词描述特性时不用进行时。</li><li>D ❌ felt 是过去时，与描述一般特性的语境不符。</li></ul><p><strong>整句翻译</strong>：这块布摸起来非常柔软舒服。</p><p><strong>词组</strong>：<code>feel soft</code> 摸起来柔软（feel 是系动词）；<code>soft and comfortable</code> 柔软又舒服</p><p><strong>对比自测</strong>：做完后对照 quiz:37，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·主动表被动第 5 条）：系动词没有被动形式，但有些常表示被动意义：taste（吃起来）、sound（听起来）、prove（证明是）、feel（摸上去）、look（看起来）、smell（闻起来）</p></details><p><strong>语态随堂练习（教材 P103，笔记补充解析）：The books sold well and ____ out last week.</strong></p><ul><li>A. are sold</li><li>B. were sold</li><li>C. sold</li><li>D. had sold</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（sold）</strong> —— 与 sold well 并列，sell 主动表被动（描绘事物特性）；last week 过去时 → sold。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are sold 是一般现在时被动，与 last week 的时间冲突。</li><li>B ❌ were sold 形式上是过去被动，与本句考点的“主动表被动”不符，也无法与前面的 sold well 保持并列语态一致。干扰点：把“书被卖掉”一律写成被动。存疑：单看 were sold out 语法上也能成立，本句取 C 是与 sold well 并列、语态一致的要求，且 sell 类动词与 out 连用表“售罄”时用主动。</li><li>C ✅ 与 sold well 并列：sell 主动表被动（描绘事物特性），last week 提示过去时 → sold。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ had sold 是过去完成时，句中缺少过去的参照点，也与并列结构不一致。</li></ul><p><strong>整句翻译</strong>：那些书很畅销，上周就卖光了。</p><p><strong>词组</strong>：<code>sell well</code> 畅销（sell 与副词连用，主动表被动）；<code>sell out</code> 卖光，售罄</p><p><strong>对比自测</strong>：做完后对照 quiz:36，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·主动表被动第 6 条）：sell, wash, clean, burn, cook 等与 well, easily, perfectly 等副词连用，描绘事物特性，主动表被动（主语 + 动词 + 副词）</p></details><p><strong>语态随堂练习（教材 P103，笔记补充解析）：The pen ____ smoothly.</strong></p><ul><li>A. writes</li><li>B. is written</li><li>C. writing</li><li>D. was written</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（writes）</strong> —— write 主动表被动，描绘笔&quot;写起来流畅&quot;的特性。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ write 与副词 smoothly 连用，描绘笔的书写特性，主动表被动；主语 The pen 单数 → writes。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ is written 是被动语态，但笔不是“被写”的对象，而是“写起来如何”。干扰点：见到笔就想“被写”。</li><li>C ❌ writing 是非谓语形式，句子会没有谓语。</li><li>D ❌ was written 是被动加过去时，语态与时态都不对。</li></ul><p><strong>整句翻译</strong>：这支笔写起来很流畅。</p><p><strong>词组</strong>：<code>write smoothly</code> 写起来流畅（write 与副词连用，主动表被动）</p><p><strong>对比自测</strong>：做完后对照 quiz:35，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·主动表被动第 6 条）：The book sells well. 这本书很畅销。</p></details><p><strong>语态随堂练习（教材 P103，笔记补充解析）：The problem ____ difficult to solve.</strong></p><ul><li>A. is seemed</li><li>B. seems</li><li>C. is seeming</li><li>D. seemed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（seems）</strong> —— seem 是系动词，没有被动语态（is seemed ✘）；描述一般情况用一般现在时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is seemed 不成立：seem 是系动词，没有被动语态。干扰点：把“被认为”的语感套到 seem 上。</li><li>B ✅ seem 是系动词，无被动；描述一般情况用一般现在时 → seems（后面 difficult to solve 里的不定式也是主动表被动）。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ is seeming 是进行时：系动词一般不用进行时。</li><li>D ❌ seemed 是过去时，与描述一般情况的语境不符。</li></ul><p><strong>整句翻译</strong>：这道题看起来很难解答。</p><p><strong>词组</strong>：<code>seem difficult to solve</code> 看起来很难解决；<code>be difficult to do</code> 难以做……（不定式用主动表被动）</p><p><strong>对比自测</strong>：做完后对照 quiz:34，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·被动语态使用（原题 why））：seem 是系动词，没有被动语态（is seemed ✘）；描述一般情况用一般现在时。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>语态练习 1：The new library ____ last month.</strong></p><ul><li>A. built</li><li>B. was built</li><li>C. has built</li><li>D. is building</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（was built）</strong> —— 笔记补充解析：last month 过去时 + 图书馆&quot;被&quot;建 → was built。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ built 是主动的过去式，图书馆不能自己建造。</li><li>B ✅ last month 是过去时间，图书馆是“被”建的 → 一般过去时被动 was built。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ has built 是主动的现在完成时，语态错、时态也不对。</li><li>D ❌ is building 是主动的现在进行时。</li></ul><p><strong>整句翻译</strong>：新图书馆上个月建成了。</p><p><strong>词组</strong>：<code>last month</code> 上个月；<code>be built</code> 被建成</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：过去 / 一般：was/were done</p></details><p><strong>语态练习 2：These books ____ to the library tomorrow.</strong></p><ul><li>A. must return</li><li>B. must be returned</li><li>C. will return</li><li>D. are returning</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（must be returned）</strong> —— 笔记补充解析：书&quot;被&quot;还，情态动词 + be done → must be returned。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ must return 是主动语态：书是“被”还的，不是书去还。干扰点：中文“书必须还”没有“被”字，就顺手写成主动。</li><li>B ✅ 情态动词 + be done：must be returned；tomorrow 表将来，由情态动词本身的“必须”承担，不再加 will。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ will return 是主动的将来时，语态不对。</li><li>D ❌ are returning 是主动的现在进行时，语态与时态都不对。</li></ul><p><strong>整句翻译</strong>：这些书明天必须还到图书馆。</p><p><strong>词组</strong>：<code>must be returned</code> 必须被归还（情态动词 + be done）；<code>return sth. to somewhere</code> 把某物归还到某处</p><p><strong>对比自测</strong>：做完后对照 quiz:45，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·被动语态的种类）：③ 情态动词 + be + 过去分词：Smoking can be shown to increase the possibility of lung cancer.</p></details><p><strong>语态练习 3：The project ____ by the end of next year.</strong></p><ul><li>A. will complete</li><li>B. will be completed</li><li>C. has completed</li><li>D. has been completed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（will be completed）</strong> —— 笔记补充解析：by the end of next year 将来时间 + 被完成 → 将来被动 will be completed。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will complete 是主动语态：项目是“被”完成的。</li><li>B ✅ by the end of next year 是将来时间，项目是“被”完成的 → 一般将来时被动 will be completed。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ has completed 是主动的现在完成时，语态与时态都不对。</li><li>D ❌ has been completed 语态对了，但现在是完成时与“明年年底”这一将来时间冲突。干扰点：看到“完成”就用完成时。</li></ul><p><strong>整句翻译</strong>：这个项目将在明年年底前完成。</p><p><strong>词组</strong>：<code>by the end of next year</code> 到明年年底为止；<code>will be completed</code> 将被完成（一般将来时的被动式）</p><p><strong>对比自测</strong>：做完后对照 quiz:45，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：将来 / 一般：will be done</p></details><p><strong>语态练习 4：A new song ____ on the radio right now.</strong></p><ul><li>A. is playing</li><li>B. is being played</li><li>C. has played</li><li>D. has been played</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is being played）</strong> —— 笔记补充解析：right now 进行中 + 歌曲&quot;被&quot;播放 → 进行被动 is being played。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is playing 是主动语态：歌是“被”播放的。</li><li>B ✅ right now 提示正在进行，歌是“被”播放的 → 现在进行时的被动式 is being played。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ has played 是主动的现在完成时，语态与时态都不对。</li><li>D ❌ has been played 语态对了，但完成时与 right now 的“正在进行”冲突。</li></ul><p><strong>整句翻译</strong>：收音机上正在播放一首新歌。</p><p><strong>词组</strong>：<code>right now</code> 此刻（现在进行时标志）；<code>is being played</code> 正在被播放（现在进行时的被动式）</p><p><strong>对比自测</strong>：做完后对照 quiz:47，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：现在 / 进行：be being done</p></details><p><strong>语态练习 5：The meeting ____ because of the heavy rain.</strong></p><ul><li>A. was canceled</li><li>B. canceled</li><li>C. has canceled</li><li>D. had canceled</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（was canceled）</strong> —— 笔记补充解析：会议&quot;被&quot;取消，过去事实 → was canceled。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 会议是“被”取消的，叙述的是过去事实 → was canceled。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ canceled 是主动的过去式：会议不能自己取消。干扰点：只改了时态，没改语态。</li><li>C ❌ has canceled 是主动的现在完成时，语态与时态都不对。</li><li>D ❌ had canceled 是主动的过去完成时，还缺少过去的参照点。</li></ul><p><strong>整句翻译</strong>：因为大雨，会议取消了。</p><p><strong>词组</strong>：<code>because of</code> 因为（后接名词）；<code>was canceled</code> 被取消（一般过去时被动）</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·被动语态的使用）：当不知道谁是动作的执行者时：The window in the classroom was broken yesterday.</p></details><p><strong>语态练习 6：Every year, a large number of books ____ in this publishing house.</strong></p><ul><li>A. publish</li><li>B. published</li><li>C. are published</li><li>D. were published</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（are published）</strong> —— 笔记补充解析：every year 一般现在被动；a large number of 修饰复数 → are published。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ publish 是主动语态：书是“被”出版的。</li><li>B ❌ published 是主动的过去式，语态与时态都不对。</li><li>C ✅ every year 提示一般现在时，书是“被”出版的 → are published；a large number of 修饰复数名词，谓语用复数。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ were published 语态对，但过去时与 every year 的一般事实冲突。</li></ul><p><strong>整句翻译</strong>：每年，这家出版社出版大量图书。</p><p><strong>词组</strong>：<code>a large number of</code> 大量的（修饰复数可数名词，谓语用复数）；<code>publishing house</code> 出版社</p><p><strong>对比自测</strong>：做完后对照 quiz:44，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·主谓一致（第 10 课））：a number of students are playing basketball on the playground.（许多……，谓语用复数）</p></details><p><strong>语态练习 7：The old bridge ____ by the workers last month.</strong></p><ul><li>A. repairs</li><li>B. repaired</li><li>C. is repaired</li><li>D. was repaired</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（was repaired）</strong> —— 笔记补充解析：last month 过去 + by the workers 被动 → was repaired。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ repairs 是主动的一般现在时，时态与语态都不对。</li><li>B ❌ repaired 是主动的过去式，后面也缺宾语。干扰点：看到 last month 就填过去式，忘了被动。</li><li>C ❌ is repaired 是被动，但一般现在时与 last month 冲突。</li><li>D ✅ by the workers 明确提示被动，last month 提示过去 → 一般过去时被动 was repaired。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：那座旧桥在上个月被工人们修好了。</p><p><strong>词组</strong>：<code>by the workers</code> 被工人们（by 引出动作发出者）；<code>last month</code> 上个月</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·被动语态的使用）：当动词承受者是叙述对象或强调动作发出者时：The thief was arrested by the police.</p></details><p><strong>语态练习 8：The new hospital ____ in two years.</strong></p><ul><li>A. builds</li><li>B. will build</li><li>C. is built</li><li>D. will be built</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（will be built）</strong> —— 笔记补充解析：in two years 将来时间 + 医院&quot;被&quot;建 → will be built。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ builds 是主动的一般现在时，语态与时态都不对。</li><li>B ❌ will build 是主动的将来时：医院不能自己建造。干扰点：时态对了就急着选。</li><li>C ❌ is built 是被动，但一般现在时与 in two years 冲突。</li><li>D ✅ in two years 是将来时间，医院是“被”建的 → will be built。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：新医院将在两年内建成。</p><p><strong>词组</strong>：<code>in two years</code> 两年后（in + 将来一段时间）；<code>will be built</code> 将被建成（一般将来时被动）</p><p><strong>对比自测</strong>：做完后对照 quiz:40，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：将来 / 一般：will be done（in + 将来一段时间，用一般将来时）</p></details><p><strong>语态练习 9：These beautiful pictures ____ by my sister since last week.</strong></p><ul><li>A. draw</li><li>B. drew</li><li>C. have drawn</li><li>D. have been drawn</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（have been drawn）</strong> —— 笔记补充解析：since last week 完成时 + by my sister 被动 → have been drawn。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ draw 是主动的一般现在时，语态与时态都不对。</li><li>B ❌ drew 是主动的过去式，既无完成义也无被动。</li><li>C ❌ have drawn 是主动语态：画是“被”画的。干扰点：数对了复数助动词，语态却漏了。</li><li>D ✅ since last week 提示完成时，by my sister 提示被动 → 现在完成时的被动式 have been drawn（主语 These pictures 复数 → have）。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：这些漂亮的画是我妹妹从上周起画的。</p><p><strong>词组</strong>：<code>since last week</code> 从上周起（完成时标志）；<code>have been drawn</code> 已被画（现在完成时的被动式）</p><p><strong>对比自测</strong>：做完后对照 quiz:30，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：现在 / 完成：have/has been done</p></details><p><strong>语态练习 10：Look! The room ____ by the cleaner now.</strong></p><ul><li>A. cleans</li><li>B. is cleaning</li><li>C. is being cleaned</li><li>D. was cleaned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（is being cleaned）</strong> —— 笔记补充解析：Look!...now 提示正在进行 + 被动 → is being cleaned。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ cleans 是主动的一般现在时，语态与时态都不对。</li><li>B ❌ is cleaning 是主动的现在进行时：房间不会自己打扫。干扰点：时态对了就选了，忘了被动。</li><li>C ✅ Look! 与 now 提示正在进行，by the cleaner 提示被动 → 现在进行时的被动式 is being cleaned。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ was cleaned 是被动，但过去时与 Look!…now 冲突。</li></ul><p><strong>整句翻译</strong>：看！房间正被清洁工打扫着。</p><p><strong>词组</strong>：<code>by the cleaner</code> 被清洁工（by 引出执行者）；<code>is being cleaned</code> 正在被打扫（现在进行时的被动式）</p><p><strong>对比自测</strong>：做完后对照 quiz:41，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·各时态下的被动语态）：现在 / 进行：be being done</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 时态本质：<strong>谓语动词随时间变化的形态</strong>；四时四态 16 种</p><p>动词变化三套规则都是&quot;<strong>直去双改</strong>&quot;（过去式 / -ing / 过去分词）</p><p>时间标志词：<strong>since 点 for 段</strong>（现在完成）；<strong>by the time + 过去 → 过去完成</strong>；<strong>by + 将来 → 将来完成</strong></p><p><strong>主将从现</strong>；行进式动词（go/come/leave/arrive...）可进行表将来</p><p><strong>been to 去过（b 有回），gone to 去了（g 未回）</strong></p><p>被动 = <strong>be + done</strong>；主动表被动口诀：<strong>need/want/worth 后 doing，系动词无被动，sell well 描特性</strong></p></div><p>延伸阅读：时态和语态 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,286),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/8/`},{default:i(()=>[...l[5]||=[e(`← 第 8 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/10/`},{default:i(()=>[...l[7]||=[e(`第 10 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};